    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-001.png",
    "question": "<p>Một nhóm học sinh đã chuẩn bị các dụng cụ: Ống nghiệm (1), nút bấc có kích thước vừa khít với miệng ống nghiệm (2), đèn cồn (3), giá đỡ thí nghiệm (4) và các điều kiện cần thiết khác để làm thí nghiệm tìm hiểu về mối liên hệ giữa nội năng của một khối khí với năng lượng của các phân tử khí. Bố trí thí nghiệm như hình bên, sau đó dùng đèn cồn hơ nóng ống nghiệm cho đến khi nút bấc bật ra khỏi miệng ống nghiệm.</p>",
