    "caption": "Hệ thống sấy lạnh & sấy thăng hoa đông trùng hạ thảo",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (DETU_11. ĐỀ SỐ 11)",
    "deBaiChung": "",
