    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-003.png",
    "question": "<p>Đông trùng hạ thảo tươi có hàm lượng nước chiếm từ $85\\%$ đến $90\\%$ khối lượng. Sau quy trình chế biến, độ ẩm thành phẩm được đưa về mức $5\\%$ đến $8\\%$. Để giữ dược tính của đông trùng hạ thảo thì có hai phương pháp phổ biến được áp dụng là sấy lạnh và sấy thăng hoa. Phương pháp sấy lạnh dựa trên nguyên lý tách ẩm bằng không khí khô, giảm áp suất để nước hóa hơi ở nhiệt độ thấp ($20^\\circ\\text{C}$ đến $30^\\circ\\text{C}$). Phương pháp sấy thăng hoa thực hiện trong điều kiện áp suất rất thấp, khiến nước đá chuyển trực tiếp sang dạng hơi ở nhiệt độ âm ($-20^\\circ\\text{C}$ đến $-5^\\circ\\text{C}$) mà không qua thể lỏng. Quy trình sấy chung gồm 3 bước:</p><ul class=\"pq-sub-list\"><li><strong>Bước 1:</strong> Xử lý nhiệt độ phù hợp cho sản phẩm và đưa vào buồng sấy kín.</li><li><strong>Bước 2:</strong> Hệ thống bơm chân không thiết lập áp suất phù hợp, đồng thời bộ gia nhiệt cung cấp năng lượng cần thiết cho quá trình chuyển pha của nước.</li><li><strong>Bước 3:</strong> Hơi nước thoát ra được thu hồi tại bộ ngưng tụ để chuyển lại thành thể lỏng, phần khí còn lại được bơm chân không loại bỏ ra ngoài môi trường.</li></ul>",
