    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Sự thăng hoa là quá trình chất chuyển trực tiếp từ thể rắn sang thể khí (hơi) mà không qua thể lỏng. Trong phương pháp sấy thăng hoa, nước đá ở thể rắn chuyển trực tiếp thành hơi nước.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Trong suốt quá trình chuyển thể (hóa hơi hoặc thăng hoa) diễn ra ở nhiệt độ không đổi, hệ vẫn cần nhận nhiệt lượng ẩn chuyển pha ($Q = mL > 0$) để phá vỡ liên kết giữa các phân tử. Do đó bộ gia nhiệt vẫn phải cung cấp nhiệt lượng ($Q \\ne 0$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Theo thuyết cấu tạo chất, lực tương tác giữa các phân tử ở thể rắn lớn hơn ở thể lỏng, và ở thể lỏng lớn hơn ở thể khí. Để đưa $1\\text{ kg}$ nước đá (rắn) thăng hoa hoàn toàn thành hơi phải tốn công thắng lực liên kết cả giai đoạn rắn $\\to$ lỏng và lỏng $\\to$ khí ($L_{\\text{thăng hoa}} \\approx \\lambda + L_{\\text{hóa hơi}}$), nên nhiệt lượng cung cấp để $1\\text{ kg}$ nước đá thăng hoa lớn hơn để $1\\text{ kg}$ nước lỏng hóa hơi.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Theo phương trình khí lí tưởng $p = nkT$ (với $n = \\frac{N}{V}$ là mật độ phân tử), khi áp suất $p$ giữ không đổi và nhiệt độ tuyệt đối $T$ tăng thì động năng trung bình của phân tử tăng nên mật độ phân tử $n$ trong buồng sấy phải giảm. Do đó số phân tử nước bị hút khỏi buồng sấy (qua bơm hút và bộ ngưng tụ) phải lớn hơn số phân tử nước thoát ra từ sản phẩm.</div>",
