    "question": "<p>Người ta dùng một lò hồ quang điện công suất $1,1 \\cdot 10^4\\text{ W}$ để nấu chảy một khối kim loại khối lượng $13,2\\text{ kg}$. Sự thay đổi nhiệt độ của khối kim loại theo thời gian được ghi lại như hình vẽ.</p>",
    "optA": "Giai đoạn $AB$ trên đồ thị tương ứng với quá trình nóng chảy của kim loại.",
    "optB": "Trong giai đoạn $BC$, khối kim loại không nhận thêm nhiệt lượng từ lò hồ quang.",
