    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Giai đoạn $AB$ (từ $T = 0$ đến $T = 11\\text{ phút}$) có nhiệt độ tăng đều từ $34^\\circ\\text{C}$ lên $659^\\circ\\text{C}$, tương ứng với quá trình nung nóng khối kim loại ở thể rắn (chưa nóng chảy).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Giai đoạn $BC$ (đoạn nằm ngang ở $659^\\circ\\text{C}$, từ $11\\text{ phút}$ đến $19\\text{ phút}$) ứng với quá trình nóng chảy của kim loại; trong giai đoạn này kim loại vẫn liên tục nhận nhiệt lượng từ lò hồ quang để chuyển từ thể rắn sang thể lỏng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Trong giai đoạn $AB$ kéo dài $\\Delta \\tau_{AB} = 11\\text{ phút} = 660\\text{ s}$, nhiệt lượng lò cung cấp làm kim loại tăng từ $34^\\circ\\text{C}$ lên $659^\\circ\\text{C}$:<div class=\"vlxt-math-callout\">$$P \\cdot \\Delta \\tau_{AB} = m c \\Delta t \\implies c = \\frac{1,1 \\cdot 10^4 \\cdot 11 \\cdot 60}{13,2 \\cdot (659 - 34)} = 880\\text{ J/(kg.K)} \\ne 440\\text{ J/(kg.K)}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Trong giai đoạn nóng chảy $BC$ kéo dài $\\Delta \\tau_{BC} = 19 - 11 = 8\\text{ phút} = 480\\text{ s}$:<div class=\"vlxt-math-callout\">$$Q_{\\text{nc}} = P \\cdot \\Delta \\tau_{BC} = \\lambda m \\implies \\lambda = \\frac{1,1 \\cdot 10^4 \\cdot 8 \\cdot 60}{13,2} = 4 \\cdot 10^5\\text{ J/kg}$$</div></div>",
