    "question": "<p>Một chiếc cốc được làm bằng kim loại đựng nước nguội, cốc không có nắp đậy. Người ta làm cho nước trong cốc chuyển từ thể lỏng thành thể khí qua 3 bước sau:</p><ul class=\"pq-sub-list\"><li><strong>Bước 1:</strong> Để cốc nước ở nơi có nắng và gió, lượng nước trong cốc giảm đi.</li><li><strong>Bước 2:</strong> Đặt cốc nước lên trên ngọn lửa đèn cồn để đun tới khi nước sôi.</li><li><strong>Bước 3:</strong> Tiếp tục đun sôi nước tới khi cạn hết thì dừng lại.</li></ul>",
