    "optB": "Ở bước 2, sự hóa hơi của nước chỉ diễn ra ở trong lòng chất lỏng.",
    "optC": "Ở bước 3, nhiệt độ của nước trong cốc tăng liên tục.",
    "optD": "Ở bước 1, lượng nước trong cốc giảm đi do có sự bay hơi.",
