    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Sự hóa hơi là quá trình chuyển thể từ thể lỏng sang thể khí (hơi), bao gồm hai hình thức là sự bay hơi và sự sôi.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Ở bước 2, trong khi đun đến lúc sôi luôn xảy ra sự bay hơi ở mặt thoáng, và ngay cả khi nước sôi thì sự hóa hơi vẫn diễn ra ở <strong>cả mặt thoáng lẫn trong lòng</strong> khối chất lỏng, không phải chỉ trong lòng chất lỏng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Ở bước 3, nước đang trong quá trình sôi ở áp suất khí quyển không đổi nên nhiệt độ của nước giữ nguyên tại nhiệt độ sôi (khoảng $100^\\circ\\text{C}$), không tăng liên tục.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Ở bước 1, nước trong cốc không nắp bị giảm khối lượng ở nhiệt độ thường do hiện tượng bay hơi diễn ra trên mặt thoáng, tốc độ bay hơi tăng mạnh nhờ nắng và gió.</div>",
