    "question": "<p>Có hai nhiệt kế thủy ngân (1) và (2) giống nhau, ban đầu đều chỉ cùng một nhiệt độ. Sau đó hai nhiệt kế được nhúng vào hai cốc nước $A$ và $B$. Sau một thời gian, mức thủy ngân trong nhiệt kế (2) cao hơn so với (1) như hình vẽ bên.</p>",
