    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Khi nhúng bầu nhiệt kế vào cốc nước đủ lâu để đạt cân bằng nhiệt, nhiệt độ của bầu thủy ngân bằng nhiệt độ của nước nên hai nhiệt kế đang đo nhiệt độ của nước trong cốc $A$ và cốc $B$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Hai nhiệt kế giống nhau (cùng thang đo và độ giãn nở nhiệt của thủy ngân), mức thủy ngân ở nhiệt kế (2) cao hơn chứng tỏ nhiệt độ nước trong cốc $B$ cao hơn cốc $A$ ($t_B > t_A$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Động năng chuyển động nhiệt trung bình của các phân tử tỉ lệ thuận với nhiệt độ tuyệt đối ($\\overline{E_\\text{đ}} = \\frac{3}{2}kT$). Vì $T_A \\lt  T_B$ nên các phân tử nước trong cốc $A$ chuyển động chậm hơn so với trong cốc $B$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Hai nhiệt kế giống hệt nhau khi cùng nhúng vào một cốc nước $A$ thì khi cân bằng nhiệt sẽ đạt cùng nhiệt độ $t_A$ và có số chỉ bằng nhau.</div>",
