    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Quan sát đồ thị, từ phút thứ $4$ trở đi đường biểu diễn nằm ngang ở giá trị không đổi $80^\\circ\\text{C}$, đây chính là nhiệt độ sôi của chất lỏng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Nhiệt độ sôi của chất lỏng phụ thuộc vào bản chất chất lỏng và áp suất trên mặt thoáng, <strong>không phụ thuộc</strong> vào công suất của nguồn nhiệt cung cấp.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Trong suốt quá trình sôi (từ phút $4$ trở đi), toàn bộ nhiệt lượng nhận được dùng để chuyển chất lỏng thành hơi nên nhiệt độ chất lỏng không thay đổi.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Khi bỏ qua hao phí, ta có $P\\tau = m c (t - t_0) \\implies t = \\frac{P}{m c}\\tau + t_0$. Khi công suất cấp nhiệt $P$ tăng thì hệ số góc $\\frac{P}{mc}$ tăng, tức độ dốc ban đầu của đồ thị tăng lên và chất lỏng đạt tới $80^\\circ\\text{C}$ sớm hơn.</div>",
