    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-010.png",
    "question": "<p>Cho $200\\text{ g}$ nước đá ở $-8^\\circ\\text{C}$ vào một cốc cách nhiệt đựng nước ở $35^\\circ\\text{C}$. Sự thay đổi nhiệt độ của nước đá và nước trong cốc theo thời gian được biểu diễn theo đồ thị hình bên. Biết nhiệt dung riêng của nước đá là $2100\\text{ J/(kg.K)}$, nhiệt nóng chảy riêng của nước đá là $3,4 \\cdot 10^5\\text{ J/kg}$, nhiệt dung riêng của nước là $4200\\text{ J/(kg.K)}$, bỏ qua nhiệt dung của cốc. Trong các phát biểu sau đây, phát biểu nào đúng, phát biểu nào sai?</p>",
    "optA": "Nước đá tan trong khoảng thời gian $\\tau_2$ giây.",
