    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Từ đồ thị, nước đá đạt $0^\\circ\\text{C}$ tại thời điểm $\\tau_1$ và tan hoàn toàn tại thời điểm $\\tau_2$, nên quá trình tan của nước đá diễn ra trong khoảng thời gian $\\tau_2 - \\tau_1$ giây (không phải $\\tau_2$ giây).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Trong khoảng thời gian từ $\\tau_1$ đến $\\tau_2$, nhiệt độ của nước đá giữ nguyên ở $0^\\circ\\text{C}$ nhưng nước đá vẫn liên tục <strong>thu nhiệt từ nước nóng</strong> trong cốc để thực hiện quá trình nóng chảy.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Vì cốc cách nhiệt, nhiệt lượng nước tỏa ra trong $\\tau_2$ giây đầu bằng tổng nhiệt lượng nước đá thu vào để tăng từ $-8^\\circ\\text{C}$ lên $0^\\circ\\text{C}$ và tan hết ở $0^\\circ\\text{C}$:<div class=\"vlxt-math-callout\">$$Q_{\\text{tỏa}} = m_{\\text{đ}} c_{\\text{đ}} \\Delta t_{\\text{đ}} + m_{\\text{đ}} \\lambda = 0,2 \\cdot 2100 \\cdot 8 + 0,2 \\cdot 3,4 \\cdot 10^5 = 71\\,360\\text{ J} = 71,36\\text{ kJ} \\ne 761,3\\text{ kJ}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Khi đạt cân bằng nhiệt tại thời điểm $\\tau_3$ ở $5^\\circ\\text{C}$, áp dụng phương trình cân bằng nhiệt:<div class=\"vlxt-math-callout\">$$Q_{\\text{tỏa}} + m_{\\text{đ}} c_n (5 - 0) = m_n c_n (35 - 5) \\implies 71\\,360 + 0,2 \\cdot 4200 \\cdot 5 = m_n \\cdot 4200 \\cdot 30 \\implies m_n \\approx 0,6\\text{ kg}$$</div></div>",
