    "question": "<p>Một nhóm học sinh làm thí nghiệm khảo sát khả năng làm nguội nước nhờ gió ở điều kiện nhiệt độ phòng $25^\\circ\\text{C}$. Nhóm sử dụng $2\\text{ kg}$ nước có nhiệt độ ban đầu là $50^\\circ\\text{C}$. Dùng quạt thổi qua chậu nước ở các chế độ khác nhau và đo nhiệt độ của nước sau mỗi phút. Biết nhiệt dung riêng của nước là $c_n = 4200\\text{ J/(kg.K)}$. Kết quả đo được ghi vào bảng như sau:</p><div class=\"vstep-data-panel\"><div class=\"vstep-data-title\"><i class=\"fa-solid fa-table-list\"></i> Bảng Kết Quả Đo Nhiệt Độ Nước Theo Thời Gian ($^\\circ\\text{C}$)</div><table class=\"vstep-data-table\"><thead><tr><th rowspan=\"2\" style=\"vertical-align: middle;\">Chế độ hoạt động</th><th colspan=\"5\">Nhiệt độ nước ($^\\circ\\text{C}$) thay đổi theo thời gian</th></tr><tr><th>1 phút</th><th>2 phút</th><th>3 phút</th><th>4 phút</th><th>5 phút</th></tr></thead><tbody><tr><td class=\"text-left\">Không có gió</td><td>46</td><td>43,5</td><td>41,5</td><td>40</td><td>39</td></tr><tr><td class=\"text-left\">Tốc độ gió nhỏ</td><td>45</td><td>42</td><td>39,5</td><td>37,8</td><td>36,5</td></tr><tr><td class=\"text-left\">Tốc độ gió lớn</td><td>43</td><td>39</td><td>36</td><td>34</td><td>32,3</td></tr></tbody></table></div>",
