    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-013.png",
    "question": "<p>Dùng đèn cồn đun nước và theo dõi nhiệt độ của băng phiến. Khi nhiệt độ của băng phiến lên tới $60^\\circ\\text{C}$ thì cứ sau $1\\text{ phút}$ lại ghi nhiệt độ và nhận xét về thể (rắn hay lỏng) của băng phiến vào bảng theo dõi. Ghi cho tới khi băng phiến đạt đến nhiệt độ $86^\\circ\\text{C}$, ta được bảng:</p><div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Thời gian đun (phút)</th><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>Thể</th><th>Thời gian đun (phút)</th><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>Thể</th></tr></thead><tbody><tr><td>0</td><td>60</td><td>Rắn</td><td>8</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>1</td><td>63</td><td>Rắn</td><td>9</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>2</td><td>66</td><td>Rắn</td><td>10</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>3</td><td>69</td><td>Rắn</td><td>11</td><td>80</td><td>Rắn và lỏng</td></tr><tr><td>4</td><td>72</td><td>Rắn</td><td>12</td><td>81</td><td>Lỏng</td></tr><tr><td>5</td><td>75</td><td>Rắn</td><td>13</td><td>82</td><td>Lỏng</td></tr><tr><td>6</td><td>77</td><td>Rắn</td><td>14</td><td>84</td><td>Lỏng</td></tr><tr><td>7</td><td>79</td><td>Rắn</td><td>15</td><td>86</td><td>Lỏng</td></tr></tbody></table></div>",
    "optA": "Nhiệt độ nóng chảy của băng phiến là $80\\text{ K}$.",
