    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Từ bảng số liệu (phút thứ $8$ đến phút $11$), nhiệt độ nóng chảy của băng phiến là $80^\\circ\\text{C}$ (tương ứng $80 + 273 = 353\\text{ K}$), không phải $80\\text{ K}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Trong suốt thời gian băng phiến tồn tại ở cả thể rắn và lỏng (từ phút $8$ đến phút $11$), nhiệt độ giữ nguyên không đổi ở $80^\\circ\\text{C}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Sau khi nóng chảy hoàn toàn, nhiệt độ băng phiến ($\\ge 80^\\circ\\text{C}$) cao hơn nhiệt độ môi trường ($30^\\circ\\text{C}$), nên khi ngừng cấp nhiệt băng phiến sẽ <strong>tỏa nhiệt ra môi trường</strong> (không thể nhận nhiệt từ môi trường lạnh hơn).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn $48\\text{ g} = 48 \\cdot 10^{-3}\\text{ kg}$ băng phiến ở nhiệt độ nóng chảy là:<div class=\"vlxt-math-callout\">$$Q = m \\lambda = 48 \\cdot 10^{-3} \\cdot 150 \\cdot 10^3 = 7200\\text{ J} = 7,2 \\cdot 10^3\\text{ J} \\ne 7,2 \\cdot 10^{-3}\\text{ J}$$</div></div>",
