    "caption": "Quạt hơi nước làm mát không khí trong phòng kín (4 m × 5 m × 4 m)",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (DETU_7. ĐỀ SỐ 07)",
    "deBaiChung": "",
    "nhomId": "",
    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-014.png",
    "question": "<p>Một quạt hơi nước là thiết bị hoạt động dựa trên nguyên tắc bốc hơi nước tự nhiên để làm mát không khí. Lúc vận hành, cánh quạt quay tròn sẽ khởi tạo lực hút không khí đi vào máy qua $3$ cửa hút gió. Ngay ở cửa lấy khí có bố trí tấm làm mát. Tấm làm mát này được thiết kế với hình thức như rất nhiều đường ống dẫn khí với mặt cắt như tổ ong. Tấm làm mát cũng có thể dẫn và thấm đẫm nước. Khi không khí nóng bên ngoài luồn qua tấm làm mát đã có nước sẽ tạo ra hiện tượng bay hơi nước hoàn toàn tự nhiên ở trong các ống dẫn không khí. Nước lúc này đang từ thể lỏng sẽ chuyển đổi thành thể khí. Khi nước bay hơi, nhiệt lượng được lấy từ không khí xung quanh, làm giảm nhiệt độ không khí. Người ta dùng quạt hơi nước để làm mát một phòng kín, kích thước $4\\text{ m} \\times 5\\text{ m} \\times 4\\text{ m}$. Giả sử toàn bộ nhiệt lượng lấy từ không khí để làm bay hơi nước và nhiệt độ của nước luôn là $35^\\circ\\text{C}$. Biết lượng nước bay hơi từ quạt trong mỗi giây là $0,7\\text{ g}$; nhiệt hóa hơi riêng của nước ở nhiệt độ $35^\\circ\\text{C}$ là $2,26 \\cdot 10^6\\text{ J/kg}$; khối lượng riêng của không khí trong phòng là $1,2\\text{ kg/m}^3$ và nhiệt dung riêng của không khí là $1005\\text{ J/(kg.K)}$.</p>",
    "optA": "Khối lượng nước trong quạt bị bay hơi trong thời gian $10\\text{ phút}$ là $0,42\\text{ kg}$.",
