    "deBaiChung": "",
    "nhomId": "",
    "hinhAnh": "",
    "question": "<p>Trộn một khối nước đá có khối lượng $0,5\\text{ kg}$ đang ở nhiệt độ $-20^\\circ\\text{C}$ vào một nhiệt lượng kế chứa $0,5\\text{ kg}$ nước đang ở nhiệt độ $30^\\circ\\text{C}$. Bỏ qua nhiệt dung của nhiệt lượng kế và sự trao đổi nhiệt với môi trường. Cho nhiệt dung riêng của nước đá và nước lần lượt là $2100\\text{ J/(kg.K)}$ và $4200\\text{ J/(kg.K)}$; nhiệt nóng chảy riêng của nước đá là $\\lambda = 3,34 \\cdot 10^5\\text{ J/kg}$.</p>",
