    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Khi cho hai vật tiếp xúc nhau, nhiệt lượng tự truyền từ vật có nhiệt độ cao ($30^\\circ\\text{C}$) sang vật có nhiệt độ thấp hơn ($-20^\\circ\\text{C}$). Do đó nước tỏa nhiệt và nước đá thu nhiệt.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Nhiệt lượng cần để đưa $0,5\\text{ kg}$ nước đá từ $-20^\\circ\\text{C}$ lên $0^\\circ\\text{C}$ là:<div class=\"vlxt-math-callout\">$$Q_1 = m_{\\text{đ}} c_{\\text{đ}} \\Delta t_1 = 0,5 \\cdot 2100 \\cdot 20 = 21\\,000\\text{ J} = 21\\text{ kJ} \\ne 21\\,000\\text{ kJ}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Nhiệt lượng để $0,5\\text{ kg}$ nước đá ở $0^\\circ\\text{C}$ tan hoàn toàn là $Q_2 = m_{\\text{đ}}\\lambda = 0,5 \\cdot 3,34 \\cdot 10^5 = 167\\,000\\text{ J}$. Nhiệt lượng tối đa nước tỏa ra khi hạ từ $30^\\circ\\text{C}$ xuống $0^\\circ\\text{C}$ là $Q_3 = m_n c_n \\Delta t_2 = 0,5 \\cdot 4200 \\cdot 30 = 63\\,000\\text{ J}$. Vì $Q_1 \\lt  Q_3 \\lt  Q_1 + Q_2$ nên nước đá chỉ tan một phần và nhiệt độ cân bằng của hệ là $0^\\circ\\text{C}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Áp dụng phương trình cân bằng nhiệt $Q_{\\text{tỏa}} = Q_{\\text{thu}}$:<div class=\"vlxt-math-callout\">$$Q_3 = Q_1 + m_{\\text{tan}} \\lambda \\implies m_{\\text{tan}} = \\frac{63\\,000 - 21\\,000}{3,34 \\cdot 10^5} \\approx 0,126\\text{ kg} = 126\\text{ g}$$</div>Vậy tổng khối lượng nước lỏng trong nhiệt lượng kế khi cân bằng là $m' = m_n + m_{\\text{tan}} = 500 + 126 = 626\\text{ g}$.</div>",
