    "question": "<p>Bảng bên dưới cho biết nhiệt dung riêng của một số chất ở điều kiện bình thường.</p>\n<div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Chất</th><th>Nhiệt dung riêng ($\\text{kJ/(kg.K)}$)</th></tr></thead><tbody><tr><td>Đồng</td><td>0,38</td></tr><tr><td>Sắt</td><td>0,46</td></tr><tr><td>Nhôm</td><td>0,88</td></tr><tr><td>Nước</td><td>4,19</td></tr></tbody></table></div>",
    "optA": "Xét các chất gồm đồng, sắt, nhôm, nước có cùng khối lượng và nhiệt độ ban đầu, nếu chúng được nhận một nhiệt lượng bằng nhau thì nước có nhiệt độ cao nhất.",
    "optB": "Đồng có nhiệt dung riêng nhỏ nhất nên tốc độ truyền nhiệt nhanh nhất.",
    "optC": "Để tăng nhiệt độ cho $176\\text{ g}$ một chất $X$ từ $25^\\circ\\text{C}$ lên đến $50^\\circ\\text{C}$ thì cần cung cấp một nhiệt lượng bằng $2026\\text{ J}$. Chất $X$ là sắt.",
    "optD": "Thả một quả cầu bằng đồng có khối lượng $300\\text{ g}$ ở $80^\\circ\\text{C}$ vào một ca nhôm có khối lượng $500\\text{ g}$ đang chứa $m\\text{ gam}$ nước ở $25^\\circ\\text{C}$, nhiệt độ của hệ khi xảy ra sự cân bằng nhiệt là $28^\\circ\\text{C}$. Bỏ qua sự trao đổi nhiệt với môi trường. Giá trị của $m$ là $367\\text{ g}$ (kết quả đã được làm tròn đến chữ số hàng đơn vị).",
    "correct": "SSĐĐ",
