    "deBaiChung": "",
    "nhomId": "",
    "hinhAnh": "",
    "question": "<p>Sau khi xác định được nhiệt dung riêng của nước là $4180\\text{ J/(kg.K)}$ và nhiệt độ nóng chảy của nước là $0^\\circ\\text{C}$, một học sinh quyết định dựa trên những số liệu này để đo nhiệt dung riêng và nhiệt nóng chảy riêng của nước đá bằng phương pháp trao đổi nhiệt với nước. Học sinh thực hiện hai lần thí nghiệm, mỗi lần đều tiến hành qua ba bước sau:</p><ul class=\"pq-sub-list\"><li><strong>(1)</strong> Lấy một lượng nước có khối lượng $m_1$ cho vào bình cách nhiệt và đo được nhiệt độ có giá trị $t_1$.</li><li><strong>(2)</strong> Lấy một lượng nước đá có khối lượng $m_2$ từ ngăn đá tủ lạnh có nhiệt độ $t_0 = -18^\\circ\\text{C}$ cho vào bình trên.</li><li><strong>(3)</strong> Chờ cho hệ cân bằng nhiệt, đo nhiệt độ bên trong bình cách nhiệt có giá trị $t_2$. Sau cùng, đổ hết nước và lau khô bình.</li></ul><p>Số liệu thí nghiệm được ghi lại trong bảng sau:</p>\n<div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Lần</th><th>$m_1\\ (\\text{g})$</th><th>$t_1\\ (^\\circ\\text{C})$</th><th>$m_2\\ (\\text{g})$</th><th>$t_2\\ (^\\circ\\text{C})$</th></tr></thead><tbody><tr><td>1</td><td>550</td><td>43,0</td><td>220</td><td>5,4</td></tr><tr><td>2</td><td>60</td><td>5,0</td><td>710</td><td>$-3{,}7$</td></tr></tbody></table></div>",
    "optA": "Trong lần 1, nước đá bị tan chảy hết trước khi hệ đạt được cân bằng nhiệt.",
