    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Ở lần 1, nhiệt độ cân bằng cuối cùng là $t_2 = 5{,}4^\\circ\\text{C} > 0^\\circ\\text{C}$ nên toàn bộ nước đá đã tan chảy hết trước khi đạt cân bằng nhiệt.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Ở lần 2, nhiệt độ cân bằng cuối cùng là $t_2 = -3{,}7^\\circ\\text{C} \\lt  0^\\circ\\text{C}$ nên toàn bộ lượng nước lỏng ban đầu đã hạ xuống $0^\\circ\\text{C}$, đông đặc hoàn toàn rồi tiếp tục giảm xuống $-3{,}7^\\circ\\text{C}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Trong lần 1, nước lỏng ban đầu nguội đi từ $43{,}0^\\circ\\text{C}$ xuống $5{,}4^\\circ\\text{C}$ nên nó <strong>tỏa nhiệt lượng</strong> (không phải hấp thụ) và độ lớn nhiệt lượng tỏa ra là:<div class=\"vlxt-math-callout\">$$Q_1 = m_1 c_1 \\Delta t_1 = 0{,}550 \\cdot 4180 \\cdot (43{,}0 - 5{,}4) \\approx 86\\,442\\text{ J} \\approx 86{,}4\\text{ kJ}$$</div>(Chú ý sai cả bản chất tỏa/thu lẫn đơn vị $\\text{J}$ so với $\\text{kJ}$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Lập hệ phương trình cân bằng nhiệt cho hai lần thí nghiệm (gọi $c_{\\text{đ}}$, $\\lambda$ là nhiệt dung riêng và nhiệt nóng chảy riêng của nước đá):<div class=\"vlxt-math-callout\">$$\\begin{cases} 0{,}550 \\cdot 4180 \\cdot (43{,}0 - 5{,}4) = 0{,}220 \\cdot \\left[c_{\\text{đ}}(0 - (-18)) + \\lambda + 4180 \\cdot (5{,}4 - 0)\\right] \\\\ 0{,}060 \\cdot \\left[4180 \\cdot (5{,}0 - 0) + \\lambda + c_{\\text{đ}}(0 - (-3{,}7))\\right] = 0{,}710 \\cdot c_{\\text{đ}} \\cdot (-3{,}7 - (-18)) \\end{cases}$$</div>Giải hệ thu được $c_{\\text{đ}} \\approx 2132\\text{ J/(kg.K)}$ và $\\lambda \\approx 332\\text{ kJ/kg}$.</div>",
