    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-022.png",
    "question": "<p>Một học sinh thực hiện thí nghiệm đo nhiệt hóa hơi riêng của nước. Một cốc thủy tinh chứa nước được đặt trên cân điện tử. Nước được đun nóng bằng bộ đun có công suất $100\\text{ W}$ được nhúng trong nước (không chạm vào thành cốc) như hình bên. Khi nước bắt đầu sôi, số chỉ của cân là $525{,}4\\text{ g}$. Sau $240\\text{ s}$ tiếp theo, số chỉ của cân là $515{,}2\\text{ g}$.</p>",
