    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Nhiệt lượng do bộ đun tỏa ra ngoài việc cung cấp cho nước hóa hơi còn bị hao phí một phần do truyền nhiệt ra cốc thủy tinh và môi trường xung quanh, nên nhiệt lượng nước thu vào nhỏ hơn nhiệt lượng bộ đun tỏa ra.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Nhiệt lượng do bộ đun công suất $\\mathcal{P} = 100\\text{ W}$ tỏa ra trong $t = 240\\text{ s}$ là:<div class=\"vlxt-math-callout\">$$Q_{\\text{tỏa}} = \\mathcal{P} \\cdot t = 100 \\cdot 240 = 24\\,000\\text{ J}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Khối lượng nước đã hóa hơi là $\\Delta m = 525{,}4 - 515{,}2 = 10{,}2\\text{ g} = 10{,}2\\cdot 10^{-3}\\text{ kg}$. Nếu bỏ qua hao phí ($|Q_{\\text{thu}}| = |Q_{\\text{tỏa}}|$):<div class=\"vlxt-math-callout\">$$L = \\frac{Q_{\\text{tỏa}}}{\\Delta m} = \\frac{24\\,000}{10{,}2\\cdot 10^{-3}} \\approx 2{,}35\\cdot 10^{6}\\text{ J/kg}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Với $L_{\\text{thực}} = 2{,}3\\cdot 10^{6}\\text{ J/kg}$, hiệu suất cung cấp nhiệt của bộ đun là:<div class=\"vlxt-math-callout\">$$H = \\frac{Q_{\\text{ích}}}{Q_{\\text{tỏa}}} = \\frac{2{,}3\\cdot 10^{6} \\cdot 10{,}2\\cdot 10^{-3}}{24\\,000} \\cdot 100\\% = 97{,}75\\% \\neq 90\\%$$</div></div>",
