    "question": "<p>Để pha một ly trà sữa, một người chuẩn bị $3$ nguyên liệu như sau: $50\\text{ g}$ nước trà ô long ở nhiệt độ $50^\\circ\\text{C}$; $10\\text{ g}$ nước đường ở nhiệt độ $20^\\circ\\text{C}$; $100\\text{ g}$ sữa tươi ở nhiệt độ $28^\\circ\\text{C}$. Cho rằng các mẫu chất lỏng này chỉ trao đổi nhiệt lẫn nhau mà không gây ra phản ứng hóa học. Thời gian pha diễn ra nhanh, bỏ qua sự trao đổi nhiệt với môi trường. Biết nhiệt dung riêng của trà, nước đường, sữa lần lượt là $c_1 = 4200\\text{ J/(kg.K)}$, $c_2 = 2280\\text{ J/(kg.K)}$, $c_3 = 3950\\text{ J/(kg.K)}$.</p>",
