    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Nhiệt độ cân bằng khi pha riêng trà ô long và nước đường là:<div class=\"vlxt-math-callout\">$$t_{12} = \\frac{m_1 c_1 t_1 + m_2 c_2 t_2}{m_1 c_1 + m_2 c_2} = \\frac{50\\cdot 10^{-3}\\cdot 4200\\cdot 50 + 10\\cdot 10^{-3}\\cdot 2280\\cdot 20}{50\\cdot 10^{-3}\\cdot 4200 + 10\\cdot 10^{-3}\\cdot 2280} \\approx 47{,}1^\\circ\\text{C} \\neq 44^\\circ\\text{C}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Nhiệt độ cân bằng khi pha riêng trà ô long và sữa tươi là:<div class=\"vlxt-math-callout\">$$t_{13} = \\frac{m_1 c_1 t_1 + m_3 c_3 t_3}{m_1 c_1 + m_3 c_3} = \\frac{50\\cdot 10^{-3}\\cdot 4200\\cdot 50 + 100\\cdot 10^{-3}\\cdot 3950\\cdot 28}{50\\cdot 10^{-3}\\cdot 4200 + 100\\cdot 10^{-3}\\cdot 3950} \\approx 35{,}6^\\circ\\text{C}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Nhiệt độ cân bằng khi pha chung cả $3$ nguyên liệu là:<div class=\"vlxt-math-callout\">$$t_{123} = \\frac{m_1 c_1 t_1 + m_2 c_2 t_2 + m_3 c_3 t_3}{m_1 c_1 + m_2 c_2 + m_3 c_3} = \\frac{10\\,500 + 456 + 11\\,060}{210 + 22{,}8 + 395} = \\frac{22\\,016}{627{,}8} \\approx 35{,}1^\\circ\\text{C}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Khi cho thêm nước đường ở nhiệt độ $t_2 = 20^\\circ\\text{C}$ vào ly trà sữa đang ở nhiệt độ cao hơn là $t_{123} \\approx 35{,}1^\\circ\\text{C}$, hỗn hợp sẽ truyền nhiệt lượng cho lượng nước đường mới thêm nên nhiệt độ sau cùng của ly trà sữa giảm xuống.</div>",
