    "question": "<p>Cho hai ly nước giống nhau, chứa cùng một lượng nước, gần đầy. Một ly được đậy kín bằng màng bọc thực phẩm, một ly không đậy. Sau khi để yên hai ly nước trong phòng một thời gian dài, ly nước không được đậy đã không còn nước trong đó. Ly nước được đậy kín có lượng nước hầu như không đổi so với ban đầu. Trên lớp màng bọc thực phẩm phía trong ly nước có một số giọt nước.</p>",
