    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Ly nước không đậy tiếp xúc trực tiếp với không khí thoáng trong phòng nên các phân tử nước trên bề mặt liên tục thoát ra ngoài và khuếch tán đi (hiện tượng bay hơi) cho đến khi cạn hết sau thời gian dài.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Các phân tử hơi nước bay lên từ mặt thoáng bị giữ lại trong không gian kín dưới màng bọc thực phẩm, khi gặp bề mặt màng bọc sẽ mất nhiệt và chuyển ngược lại thành thể lỏng (hiện tượng ngưng tụ) tạo thành các giọt nước bám bên trong.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Sự bay hơi trong ly đậy kín <strong>không hề dừng lại</strong>; các phân tử nước vẫn liên tục thoát khỏi mặt thoáng, nhưng đạt tới trạng thái <strong>cân bằng động</strong> với quá trình ngưng tụ ngược trở lại.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Trong không gian kín phía trên ly nước đậy màng bọc, mật độ hơi nước tăng nhanh tới mức bão hòa, khiến tốc độ các phân tử hơi nước <strong>ngưng tụ</strong> quay trở lại mặt nước bằng với tốc độ phân tử nước bay hơi, nhờ vậy mực nước hầu như không đổi.</div>",
