    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-026.png",
    "question": "<p>Cầu chì là một thiết bị an toàn điện hoạt động dựa trên tác dụng nhiệt của dòng điện. Một cầu chì ống sử dụng dây chì hình trụ có khối lượng $m = 2\\text{ g}$. Biết nhiệt dung riêng và nhiệt nóng chảy riêng của chì lần lượt là $130\\text{ J/(kg.K)}$ và $0{,}25\\cdot 10^5\\text{ J/kg}$, nhiệt độ nóng chảy của chì là $327^\\circ\\text{C}$ và nhiệt độ của môi trường phòng là $27^\\circ\\text{C}$.</p>",
