    "optC": "Nhiệt lượng cần cung cấp để nung nóng dây chì từ nhiệt độ phòng đến nhiệt độ nóng chảy là $78\\text{ J}$.",
    "optD": "Nhiệt lượng cần thiết để làm dây chì nóng chảy hoàn toàn tại nhiệt độ nóng chảy lớn hơn nhiệt lượng cần để nung nóng nó từ nhiệt độ phòng đến nhiệt độ nóng chảy.",
