    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Khi mạch điện quá tải hoặc ngắn mạch, cường độ dòng điện tăng vọt làm dây chì tỏa nhiệt Joule mạnh, nóng lên đạt tới $327^\\circ\\text{C}$ và nóng chảy đứt rời, tự động ngắt mạch bảo vệ thiết bị.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Chì dẫn điện <strong>kém hơn đồng</strong> và có <strong>nhiệt độ nóng chảy thấp</strong> ($327^\\circ\\text{C}$ so với $1084^\\circ\\text{C}$ của đồng), nhờ đó dây cầu chì kịp nóng chảy ngắt mạch trước khi dây dẫn đồng bị quá nhiệt gây hỏa hoạn.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Nhiệt lượng cần thiết để nung nóng dây chì từ $27^\\circ\\text{C}$ lên $327^\\circ\\text{C}$ là:<div class=\"vlxt-math-callout\">$$Q = m c \\Delta t = 2\\cdot 10^{-3} \\cdot 130 \\cdot (327 - 27) = 78\\text{ J}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Nhiệt lượng cần thiết để làm nóng chảy hoàn toàn dây chì tại nhiệt độ nóng chảy $327^\\circ\\text{C}$ là:<div class=\"vlxt-math-callout\">$$Q' = m \\lambda = 2\\cdot 10^{-3} \\cdot 0{,}25\\cdot 10^5 = 50\\text{ J}$$</div>Ta thấy $Q' = 50\\text{ J} \\lt  Q = 78\\text{ J}$.</div>",
