    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-027.png",
    "question": "<p>Một thợ kim hoàn dùng lò điện để nấu chảy hỗn hợp gồm $0{,}8\\text{ kg}$ đồng và $0{,}2\\text{ kg}$ bạc nhằm tạo hợp kim đồng – bạc. Biết nhiệt độ ban đầu của hỗn hợp là $27^\\circ\\text{C}$. Các thông số của đồng và bạc được cho như bảng trong hình bên. Lò điện có công suất $2{,}5\\text{ kW}$ và hiệu suất $60\\%$.</p>",
