    "question": "<p>Một nhóm học sinh thực hiện thí nghiệm khảo sát quá trình làm nguội của nước. Nhóm sử dụng hai chậu giống nhau, mỗi chậu chứa $2\\text{ kg}$ nước nóng có nhiệt độ ban đầu là $50^\\circ\\text{C}$. Thí nghiệm được tiến hành trong phòng có nhiệt độ $25^\\circ\\text{C}$. Chậu 1 để nguội tự nhiên và chậu 2 dùng quạt thổi gió qua mặt thoáng. Trong quá trình đo, học sinh liên tục khuấy nhẹ nước và phòng lặng gió. Kết quả đo nhiệt độ nước sau mỗi phút được ghi lại như bảng và hình bên dưới.</p>",
