    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Nhiệt độ ban đầu của nước ($50^\\circ\\text{C}$) cao hơn nhiệt độ phòng ($25^\\circ\\text{C}$) nên theo nguyên lý truyền nhiệt, nước trong cả hai chậu đều tự truyền nhiệt lượng ra môi trường xung quanh.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Nhiệt độ của nước ở chậu 2 giảm nhanh hơn chậu 1 (từ $50^\\circ\\text{C}$ xuống $32{,}3^\\circ\\text{C}$ so với $39^\\circ\\text{C}$ sau $5\\text{ phút}$) là do có luồng gió quạt thổi qua mặt thoáng làm hơi nước khuếch tán đi nhanh, khiến quá trình bay hơi diễn ra <strong>nhanh hơn</strong> và lấy đi nhiều nhiệt lượng hơn.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Nước dẫn nhiệt kém và dễ phân tầng nhiệt độ theo độ sâu; việc khuấy nhẹ liên tục tạo đối lưu giúp nhiệt độ ở mọi vùng trong chậu đồng đều, tránh sai số cục bộ khi đọc nhiệt kế.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Do tốc độ bay hơi trên mặt thoáng ở chậu 2 nhanh hơn chậu 1, lượng nước đã hóa hơi thoát ra ngoài ở chậu 2 nhiều hơn, nên tại phút thứ 5 <strong>khối lượng nước còn lại ở chậu 2 nhỏ hơn ở chậu 1</strong>.</div>",
