    "question": "<p>Hình vẽ bên cho thấy đồ thị biểu diễn sự biến thiên của nhiệt độ $t$ theo thời gian $\\tau$ trong quá trình nung nóng một thỏi chì có khối lượng $1\\text{ kg}$. Biết nhiệt dung riêng của chì là $130\\text{ J/(kg.K)}$.</p>",
