    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Khi chì chuyển từ $B$ sang $C$ (đoạn nằm ngang ở $327^\\circ\\text{C}$), chì đang nóng chảy và liên tục nhận nhiệt lượng ($Q > 0$) để phá vỡ liên kết tinh thể nên <strong>nội năng của chì tăng</strong> ($\\Delta U > 0$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Trong $\\tau_{15} = 15\\text{ phút}$ đầu, nhiệt độ thỏi chì tăng đều từ $27^\\circ\\text{C}$ lên $327^\\circ\\text{C}$ ($\\Delta T = 300\\text{ K}$). Với công suất cấp nhiệt $\\mathcal{P}$ không đổi:<div class=\"vlxt-math-callout\">$$\\begin{cases} \\mathcal{P} \\tau_{15} = m c \\Delta T \\\\ \\mathcal{P} \\tau_8 = \\Delta U \\end{cases} \\implies \\Delta U = m c \\Delta T \\cdot \\frac{\\tau_8}{\\tau_{15}} = 1 \\cdot 130 \\cdot (327 - 27) \\cdot \\frac{8}{15} = 20\\,800\\text{ J}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> $27^\\circ\\text{C}$ là nhiệt độ ban đầu của thỏi chì tại $\\tau = 0$. Quá trình nóng chảy (đoạn nằm ngang $BC$) xảy ra ở nhiệt độ không đổi bằng <strong>$327^\\circ\\text{C}$</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Tại điểm $B$ ($\\tau = 15\\text{ phút}$, $t = 327^\\circ\\text{C}$), thỏi chì vừa đạt tới nhiệt độ nóng chảy và <strong>bắt đầu nóng chảy</strong> nên tại $B$ chì đang ở <strong>trạng thái rắn</strong>.</div>",
