    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Trên đồ thị, từ $t = 0$ đến $10\\text{ phút}$ chia thành $5$ ô (mỗi ô ứng với $2\\text{ phút}$). Sau $4\\text{ phút}$ ($2$ ô), nhiệt độ của nước là $40^\\circ\\text{C}$, đổi sang thang Kelvin là $T = 40 + 273 = 313\\text{ K} \\neq 333\\text{ K}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Sau $10\\text{ phút}$ kể từ $t = 0$, nhiệt độ của nước tăng từ $0^\\circ\\text{C}$ lên $100^\\circ\\text{C}$, tức độ tăng nhiệt độ là $\\Delta T = \\Delta t = 100 - 0 = 100\\text{ K}$ (không phải tăng thêm $373\\text{ K}$; $373\\text{ K}$ là giá trị nhiệt độ lúc sôi chứ không phải độ tăng).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Quan sát đồ thị: tại $t = 10\\text{ phút}$ (điểm $B$), nhiệt độ đạt $100^\\circ\\text{C}$ và bắt đầu giữ nguyên nằm ngang sang $C$ (đến $14\\text{ phút}$), chứng tỏ nước bắt đầu sôi sau $10\\text{ phút}$ kể từ $t = 0$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Tại $t_1 = 14\\text{ phút}$ (điểm $C$), nhiệt độ của nước là $100^\\circ\\text{C}$; tại $t_2 = 20\\text{ phút}$ (điểm $D$), đoạn đồ thị dừng ở mức cao hơn vạch $20^\\circ\\text{C}$ (khoảng $26^\\circ\\text{C}$–$27^\\circ\\text{C}$). Do đó nhiệt độ nước chỉ giảm khoảng $73^\\circ\\text{C}$–$74^\\circ\\text{C}$, nhỏ hơn $80^\\circ\\text{C}$.</div>",
