    "question": "<p>Bố trí thí nghiệm đo nhiệt nóng chảy riêng của nước đá như hình bên, nguồn nhiệt có công suất $56\\text{ W}$. Kết quả thí nghiệm cho ở bảng trong hình.</p>",
