    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Trong suốt thí nghiệm, phễu nước đá ở $0^\\circ\\text{C}$ thấp hơn nhiệt độ phòng nên nước đá vừa nhận nhiệt lượng tỏa ra từ nguồn nhiệt $56\\text{ W}$, vừa nhận thêm nhiệt lượng truyền vào từ môi trường xung quanh.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Khi tắt nguồn nhiệt, trong $485\\text{ s}$ số chỉ của cân vẫn tăng từ $116{,}5\\text{ g}$ lên $124{,}6\\text{ g}$, chứng tỏ nước đá vẫn tiếp tục tan do nhận nhiệt từ môi trường xung quanh.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Khi tắt nguồn nhiệt ($485\\text{ s}$), lượng nước đá tan do môi trường là $\\Delta m_0 = 124{,}6 - 116{,}5 = 8{,}1\\text{ g}$. Khi bật nguồn nhiệt ($485\\text{ s}$), tổng lượng nước đá tan thêm là $\\Delta m_{\\text{tổng}} = 215 - 124{,}6 = 90{,}4\\text{ g}$. Do đó lượng nước đá tan chỉ do nguồn nhiệt là:<div class=\"vlxt-math-callout\">$$\\Delta m = \\Delta m_{\\text{tổng}} - \\Delta m_0 = 90{,}4 - 8{,}1 = 82{,}3\\text{ g}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Nhiệt nóng chảy riêng của nước đá tính được từ thí nghiệm là:<div class=\"vlxt-math-callout\">$$\\lambda = \\frac{\\mathcal{P} \\cdot t}{\\Delta m} = \\frac{56 \\cdot 485}{82{,}3\\cdot 10^{-3}} \\approx 330\\,012\\text{ J/kg} \\approx 330\\text{ kJ/kg}$$</div></div>",
    "isApproved": true,
    "batchId": "BATCH_DS106_OFFICIAL_20261118"
