    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-035.png",
    "question": "<p>Một nhóm học sinh thực hiện thí nghiệm kiểm chứng định luật Charles. Bộ thí nghiệm gồm các dụng cụ lắp đặt như hình vẽ. Ống thuỷ tinh đầu dưới bịt kín, đầu trên hở, bên trong có giọt acid sulfuric ngăn khí trong ống không thoát ra ngoài. Nhóm tiến hành đo chiều cao của cột khí trong ống ở các nhiệt độ khác nhau và ghi lại kết quả như sau:</p><div class=\"vstep-data-panel\"><table class=\"vstep-data-table\"><thead><tr><th>Nhiệt độ ($^\\circ\\text{C}$)</th><th>$25$</th><th>$30$</th><th>$35$</th><th>$40$</th><th>$45$</th><th>$50$</th><th>$55$</th><th>$60$</th><th>$65$</th></tr></thead><tbody><tr><td>Chiều cao cột khí ($\\text{cm}$)</td><td>$9{,}5$</td><td>$9{,}6$</td><td>$9{,}8$</td><td>$10{,}0$</td><td>$10{,}1$</td><td>$10{,}3$</td><td>$10{,}5$</td><td>$10{,}7$</td><td>$10{,}8$</td></tr></tbody></table></div>",
    "optA": "Khi giọt acid sulfuric đứng yên ở các vị trí khác nhau, áp suất cột khí trong các trường hợp bằng nhau.",
