    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Xilanh đặt nằm ngang, bỏ qua ma sát và pít-tông dịch chuyển chậm (từ từ), nên áp suất của khí bên trong luôn cân bằng với áp suất khí quyển bên ngoài ($p = p_0 = \\text{hằng số}$). Quá trình dãn nở của khối khí là <strong>quá trình đẳng áp</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Theo định luật Charles ($\\dfrac{V}{T} = \\text{hằng số}$), khi khí dãn nở đẳng áp ($V$ tăng) thì nhiệt độ tuyệt đối $T$ tăng. Vì động năng tịnh tiến trung bình $\\overline{E_{\\text{đ}}} = \\dfrac{3}{2}kT$ tỉ lệ thuận với $T$, nên động năng trung bình của các phân tử khí tăng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Do quá trình biến đổi là <strong>đẳng áp</strong> ($p = \\text{hằng số}$), nếu nhiệt độ tuyệt đối $T$ của khối khí tăng lên $3$ lần thì <strong>thể tích $V$ tăng lên $3$ lần</strong>, còn áp suất khí không thay đổi.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Nội năng của một lượng khí lí tưởng chỉ phụ thuộc vào nhiệt độ ($U = \\dfrac{i}{2}nRT$). Khi được hơ nóng, nhiệt độ $T$ và động năng trung bình của các phân tử tăng nên <strong>nội năng của khí tăng</strong> (không giảm).</div>",
