    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-037.png",
    "question": "<p>Cho một lượng khí Helium (coi là khí lý tưởng) thực hiện chu trình $1 - 2 - 3 - 4 - 1$ được biểu diễn trên đồ thị $P - V$ như hình vẽ. Cho $P_0 = 10^5\\text{ Pa}$; $V_0 = 2\\text{ lít}$.</p>",
