    "question": "<p>Túi khí xe ô tô là một phần của hệ thống an toàn được thiết kế để bảo vệ người lái và hành khách trong trường hợp va chạm vượt ngưỡng nguy hiểm. Cấu tạo túi khí ô tô được xây dựng từ ba thành phần chính: hệ thống cảm biến, bộ phận kích nổ và túi khí (được làm từ sợi tổng hợp, co giãn tốt, chịu lực cao, chống nhiệt và chống cháy tốt). Khi có sự va chạm xảy ra, những tín hiệu từ hệ thống cảm biến được truyền tới bộ điều khiển túi khí. Bộ phận kích nổ sẽ tạo ra một lượng lớn khí $\\text{N}_2$ để làm phồng túi khí nhanh chóng, bảo vệ an toàn cho người ngồi trên xe, đồng thời khí bên trong túi cũng xì hơi nhanh qua các lỗ thoát khí để tránh gây áp lực lên cơ thể. Một túi khí tiêu chuẩn có thể tích xấp xỉ $60\\text{ lít}$ khi được bơm căng ở $25^\\circ\\text{C}$ và chịu được áp suất tối đa lên đến $5\\text{ psi}$ ($1\\text{ psi} \\approx 6{,}895\\text{ kPa}$).</p>",
