    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Khi xảy ra va chạm mạnh, cảm biến kích hoạt bộ phận kích nổ sinh lượng lớn khí $\\text{N}_2$ làm túi khí phồng lên cực nhanh, tạo đệm hơi đàn hồi giúp kéo dài thời gian hãm và giảm chấn thương cho người ngồi trên xe.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Đổi đơn vị áp suất tối đa từ $\\text{psi}$ sang $\\text{kPa}$:<div class=\"vlxt-math-callout\">$$p_{\\max} = 5\\text{ psi} \\approx 5 \\cdot 6{,}895\\text{ kPa} = 34{,}475\\text{ kPa}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Với $p = 3\\text{ psi} \\approx 3 \\cdot 6{,}895 \\cdot 10^3\\text{ Pa}$, $V = 60\\text{ lít} = 60\\cdot 10^{-3}\\text{ m}^3$ và $T = 25 + 273 = 298\\text{ K}$, áp dụng phương trình Clapeyron – Mendeleev:<div class=\"vlxt-math-callout\">$$pV = nRT \\implies n = \\dfrac{pV}{RT} = \\dfrac{3 \\cdot 6{,}895\\cdot 10^3 \\cdot 60\\cdot 10^{-3}}{8{,}31 \\cdot 298} \\approx 0{,}50\\text{ mol}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Để kịp bảo vệ trước va đập, túi khí bung nở với vận tốc và lực đẩy rất lớn nên vẫn có thể gây chấn thương nếu không thắt dây an toàn hoặc ngồi quá gần; đặc biệt trẻ nhỏ không nên ngồi ở ghế trước và cần kết hợp dây an toàn đúng quy chuẩn.</div>",
