    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-039.png",
    "question": "<p>Một nhóm học sinh thiết lập sơ đồ thí nghiệm như hình bên để “nghiên cứu mối liên hệ giữa áp suất và thể tích của một khối khí nhất định ở nhiệt độ không đổi”.</p><ul><li>Trong hình, thiết bị thí nghiệm $A$ là ____ $(1)$.</li><li>Nhóm học sinh đã đo hai bộ dữ liệu $(p, V)$ khác nhau trong hai thí nghiệm khác nhau và thấy rằng tích của $p$ và $V$ trong hai bộ dữ liệu khác nhau đáng kể, lí do có thể là ____ $(2)$.</li><li>Để giữ nhiệt độ của khí trong xilanh không đổi, biện pháp được thực hiện trong thí nghiệm là ____ $(3)$.</li><li>Ban đầu khí trong xilanh có thể tích $10\\text{ cm}^3$ và áp suất bằng áp suất khí quyển bên ngoài là $p_0$. Trong quá trình thí nghiệm, thể tích khí trong xilanh thay đổi từ $4\\text{ cm}^3$ đến $20\\text{ cm}^3$. Chênh lệch áp suất khí bên trong xilanh và bên ngoài lớn nhất là ____ $(4)$.</li></ul>",
    "optA": "(1): cảm biến nhiệt độ.",
    "optB": "(2): nhiệt độ môi trường khác nhau và khối lượng khí trong xilanh khác nhau.",
    "optC": "(3): tay giữ chắc phần thân xilanh và đẩy kéo piston dứt khoát.",
    "optD": "(4): $1{,}5p_0$",
    "correct": "ĐĐSĐ",
