    "question": "<p>Bóng thám không được sử dụng để thu thập thông tin về môi trường, không khí và thời tiết. Vỏ bóng được làm bằng chất liệu đàn hồi, phía dưới có gắn dù và thiết bị đo (hình bên). Bóng thường được bơm khí hiếm nhẹ hơn không khí, nhờ đó có thể bay lên các tầng không khí khác nhau để thu thập thông tin về nhiệt độ, độ ẩm, áp suất, tốc độ gió,... Một quả bóng thám không khi bắt đầu thả có đường kính $3\\text{ m}$. Vỏ bóng, dù và thiết bị đo có khối lượng $4\\text{ kg}$. Bóng được bơm khí hydrogen, ở áp suất bằng áp suất khí quyển tại mặt đất $p_0 = 1{,}013\\cdot 10^5\\text{ Pa}$ và nhiệt độ $27^\\circ\\text{C}$. Bóng lên đến độ cao $h$ thì dừng lại, khi đó đường kính của bóng đã tăng gấp $3$ lần so với khi bắt đầu thả, tại đó nhiệt độ của khí quyển là $-55^\\circ\\text{C}$ và lơ lửng trên đó khoảng $2\\text{ giờ}$ trước khi vỡ. Biết khối lượng mol của không khí và của hydrogen lần lượt là $29\\text{ g/mol}$ và $2\\text{ g/mol}$.</p>",
