    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Để bóng bay lên được, lực đẩy Archimedes của không khí tác dụng lên bóng phải thắng <strong>tổng trọng lượng của vỏ bóng, dù, thiết bị đo VÀ trọng lượng của lượng khí $\\text{H}_2$ bên trong bóng</strong> ($F_A > \\sum P = P_{\\text{vỏ, dù, thiết bị}} + P_{\\text{khí}}$). Phát biểu a bỏ sót trọng lượng của khí bên trong bóng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Càng lên cao áp suất khí quyển bên ngoài càng giảm; khi chênh lệch áp suất giữa khí bên trong và bên ngoài tăng lên, thể tích vỏ bóng đàn hồi giãn nở to ra, làm thành vỏ mỏng dần đến giới hạn bền thì bóng sẽ bị vỡ.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Tại mặt đất, bán kính bóng $R_1 = 1{,}5\\text{ m}$, thể tích $V_1 = \\dfrac{4}{3}\\pi R_1^3 = \\dfrac{4}{3}\\cdot 3{,}14\\cdot 1{,}5^3 \\approx 14{,}13\\text{ m}^3$, $T_1 = 27 + 273 = 300\\text{ K}$. Theo phương trình Clapeyron – Mendeleev:<div class=\"vlxt-math-callout\">$$p_0 V_1 = \\dfrac{m_{\\text{H}_2}}{M_{\\text{H}_2}} R T_1 \\implies m_{\\text{H}_2} = \\dfrac{1{,}013\\cdot 10^5 \\cdot 14{,}13 \\cdot 2\\cdot 10^{-3}}{8{,}31 \\cdot 300} \\approx 1{,}15\\text{ kg} \\neq 1{,}51\\text{ kg}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Tại độ cao $h$, bán kính $R_2 = 3R_1 = 4{,}5\\text{ m}$, $T_2 = -55 + 273 = 218\\text{ K}$. Khi bóng đứng yên lơ lửng, lực đẩy Archimedes cân bằng với tổng trọng lượng $\\rho_{\\text{kq}} V_2 g = (m_{\\text{vỏ}} + m_{\\text{H}_2})g$:<div class=\"vlxt-math-callout\">$$p_{\\text{kq}} = \\dfrac{m_{\\text{vỏ}} + m_{\\text{H}_2}}{V_2}\\cdot \\dfrac{R T_2}{M_{\\text{kq}}} = \\dfrac{4 + 1{,}15}{\\frac{4}{3}\\cdot 3{,}14\\cdot 4{,}5^3}\\cdot \\dfrac{8{,}31 \\cdot 218}{29\\cdot 10^{-3}} \\approx 843{,}3\\text{ Pa} \\approx 8{,}4\\cdot 10^2\\text{ Pa}$$</div></div>",
