    "question": "<p>Một ngôi nhà có thể tích phần không gian bên trong là $40\\text{ m}^3$. Vào một ngày mùa đông, nhiệt độ trong ngôi nhà vào buổi sáng sớm là $20^\\circ\\text{C}$ và đến giữa trưa là $25^\\circ\\text{C}$. Cho biết áp suất khí quyển không đổi trong ngày là $1\\text{ atm} = 1{,}013\\cdot 10^5\\text{ Pa}$ và khối lượng mol của không khí là $29\\text{ g/mol}$.</p>",
