    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Độ tăng nhiệt độ trong thang Kelvin bằng đúng độ tăng nhiệt độ trong thang Celsius: $\\Delta T = \\Delta t = 25 - 20 = 5\\text{ K}$ (không phải $278\\text{ K}$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Nhiệt độ buổi trưa ($25^\\circ\\text{C}$) cao hơn buổi sáng ($20^\\circ\\text{C}$), nên động năng tịnh tiến trung bình của phân tử khí $\\overline{E_{\\text{đ}}} = \\dfrac{3}{2}kT$ lớn hơn và các phân tử chuyển động nhiệt nhanh hơn.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Áp dụng phương trình Clapeyron – Mendeleev ở buổi sáng sớm ($T_1 = 20 + 273 = 293\\text{ K}$):<div class=\"vlxt-math-callout\">$$pV = \\dfrac{N_1}{N_A}RT_1 \\implies N_1 = \\dfrac{1{,}013\\cdot 10^5 \\cdot 40 \\cdot 6{,}02\\cdot 10^{23}}{8{,}31 \\cdot 293} \\approx 10{,}02\\cdot 10^{26}\\text{ phân tử} \\neq 7{,}51\\cdot 10^{26}\\text{ phân tử}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Áp suất và thể tích phòng không đổi ($T_1 = 293\\text{ K}$, $T_2 = 298\\text{ K}$), khối lượng không khí thoát ra ngoài từ sáng sớm đến giữa trưa là:<div class=\"vlxt-math-callout\">$$\\Delta m = m_1 - m_2 = \\dfrac{pVM}{R}\\left(\\dfrac{1}{T_1} - \\dfrac{1}{T_2}\\right) = \\dfrac{1{,}013\\cdot 10^5 \\cdot 40 \\cdot 29\\cdot 10^{-3}}{8{,}31}\\left(\\dfrac{1}{293} - \\dfrac{1}{298}\\right) \\approx 0{,}81\\text{ kg}$$</div></div>",
    "isApproved": true,
