    "question": "<p>Trong ô tô, người ta thường đặt ở hệ thống tay lái một thiết bị nhằm bảo vệ người lái xe khi xe gặp tai nạn, gọi là “túi khí”. Trong túi khí thường chứa $87\\text{ g}$ chất $\\text{NaN}_3$, khi va chạm mạnh vào vật cản thì hệ thống cảm biến của xe sẽ kích thích chất rắn này làm nó phân hủy tạo thành $\\text{Na}$ và khí Nitơ. Khí Nitơ được tạo thành sẽ làm túi khí phồng lên, giúp người lái xe không va chạm trực tiếp vào hệ thống lái.</p>",
