    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Túi khí được chế tạo từ vật liệu sợi tổng hợp co giãn tốt và chịu được áp suất lớn để phồng nhanh khi va chạm mà không rách vỡ.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Khí Nitơ là phân tử $\\text{N}_2$ (không phải $\\text{N}_3$), nên phương trình hóa học phân hủy Natri azua đúng phải là: $2\\text{NaN}_3 \\to 2\\text{Na} + 3\\text{N}_2$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Số mol $\\text{NaN}_3$ là $n = \\dfrac{87}{23 + 14\\cdot 3} = \\dfrac{87}{65}\\text{ mol}$. Theo phương trình $2\\text{NaN}_3 \\to 2\\text{Na} + 3\\text{N}_2$, số mol và thể tích khí $\\text{N}_2$ tạo thành là:<div class=\"vlxt-math-callout\">$$n' = \\dfrac{87}{65}\\cdot\\dfrac{3}{2} = \\dfrac{261}{130}\\text{ mol} \\implies V_{\\text{N}_2} = \\dfrac{261}{130}\\cdot 24{,}0 \\approx 48{,}18\\text{ lít} \\approx 48\\text{ lít}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Áp dụng phương trình Clapeyron – Mendeleev với $T = 37 + 273 = 310\\text{ K}$:<div class=\"vlxt-math-callout\">$$p = \\dfrac{n'RT}{V} = \\dfrac{\\frac{261}{130}\\cdot 8{,}31\\cdot 310}{\\frac{261}{130}\\cdot 24{,}0\\cdot 10^{-3}} = 107\\,337{,}5\\text{ Pa} \\approx 107{,}34\\text{ kPa}$$</div></div>",
