    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-045.png",
    "question": "<p>Một mol khí lí tưởng thực hiện chu trình biến đổi được biểu diễn bằng đồ thị như hình vẽ bên dưới. Biết $p_1 = 8{,}31 \\cdot 10^5\\text{ Pa}$; $T_1 = 300\\text{ K}$; $p_2 = 13{,}85 \\cdot 10^5\\text{ Pa}$.</p>\n<ul class=\"pq-sub-list\">\n<li>Giai đoạn $(1)$ sang $(2)$: đồ thị là một phần của nhánh Parabol có đỉnh tại gốc tọa độ $O$ (phương trình Parabol này có dạng $T = aV^2$ với $a$ là hằng số tính theo đơn vị $\\text{K/m}^6$);</li>\n<li>Giai đoạn $(2)$ sang $(3)$: đồ thị là một đoạn thẳng có đường kéo dài vuông góc với trục $OV$;</li>\n<li>Giai đoạn $(3)$ về $(1)$: đồ thị là một đoạn thẳng kéo dài đi qua gốc tọa độ $O$.</li>\n</ul>",
    "optA": "Đường $2 - 3$ biểu diễn quá trình đẳng nhiệt.",
    "optB": "Đường $3 - 1$ biểu diễn quá trình đẳng áp.",
