    "caption": "Xi lanh thép nằm ngang có ma sát pít-tông: dãn nở 30 cm rồi co lại 25 cm",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (2)",
    "deBaiChung": "",
