    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-047.png",
    "question": "<p>Một lượng khí helium (xem là khí lí tưởng) có số mol là $0{,}1\\text{ mol}$ được chứa trong một xi lanh kín, phía trên là pít-tông có thể chuyển động thẳng đứng không ma sát. Ban đầu, khi pít-tông cân bằng, nhiệt độ của khối khí là $27^\\circ\\text{C}$. Người ta đặt thêm lên pít-tông một quả nặng có khối lượng $15\\text{ kg}$, làm pít-tông dịch chuyển đi xuống một đoạn $d$ như hình vẽ bên dưới. Quá trình nén khí diễn ra đẳng nhiệt. Biết áp suất khí quyển là $10^5\\text{ Pa}$, tiết diện ngang của pít-tông bằng $1{,}25\\text{ dm}^2$, gia tốc trọng trường $g = 10\\text{ m/s}^2$. Bỏ qua khối lượng của pít-tông.</p>",
    "optA": "Thể tích ban đầu của khối khí helium là $2{,}493\\text{ lít}$.",
