    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Ban đầu pít-tông không khối lượng cân bằng nên $p_1 = p_0 = 10^5\\text{ Pa}$. Áp dụng phương trình Clapeyron:<div class=\"vlxt-math-callout\">$$p_1 V_1 = n R T_1 \\implies V_1 = \\frac{n R T_1}{p_0} = \\frac{0{,}1 \\cdot 8{,}31 \\cdot (27 + 273)}{10^5} = 2{,}493 \\cdot 10^{-3}\\text{ m}^3 = 2{,}493\\text{ lít}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Sau khi đặt thêm quả nặng khối lượng $m = 15\\text{ kg}$ lên pít-tông có tiết diện $S = 1{,}25\\text{ dm}^2 = 1{,}25 \\cdot 10^{-2}\\text{ m}^2$:<div class=\"vlxt-math-callout\">$$p_2 = p_0 + \\frac{mg}{S} = 10^5 + \\frac{15 \\cdot 10}{1{,}25 \\cdot 10^{-2}} = 1{,}12 \\cdot 10^5\\text{ Pa}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Quá trình nén diễn ra đẳng nhiệt nên theo định luật Boyle:<div class=\"vlxt-math-callout\">$$p_1 V_1 = p_2 V_2 \\implies V_2 = \\frac{p_1 V_1}{p_2} = \\frac{10^5 \\cdot 2{,}493}{1{,}12 \\cdot 10^5} \\approx 2{,}226\\text{ lít}$$</div>Độ dịch chuyển đi xuống của pít-tông:<div class=\"vlxt-math-callout\">$$d = \\frac{V_1 - V_2}{S} = \\frac{2{,}493 - 2{,}226}{1{,}25} = 0{,}2136\\text{ dm} \\approx 2\\text{ cm}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Nội năng của khí lí tưởng chỉ phụ thuộc vào nhiệt độ tuyệt đối ($U = \\dfrac{3}{2} n R T$ đối với khí đơn nguyên tử He). Vì quá trình nén là <strong>đẳng nhiệt</strong> ($T = \\text{const}$) nên nội năng của khối khí helium <strong>không đổi</strong>.</div>",
