    "simType": "U_TUBE_MERCURY_KR",
    "caption": "Ống chữ U chứa thủy ngân nối bình khí nén Kripton (5 atm) ở nhánh trái bịt kín",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (9)",
    "deBaiChung": "",
    "nhomId": "",
    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-052.png",
    "question": "<p>Cho một ống chữ U có tiết diện đều $S = 3\\text{ cm}^2$, hở hai đầu, đặt trong không khí, chứa thủy ngân. Ban đầu mực thủy ngân ở hai cột cao bằng nhau. Bịt kín một đầu ống lại bằng nút bấc (phần nút bấc lọt vào trong ống có thể tích không đáng kể). Cho áp suất khí quyển là $p_0 = 1\\text{ atm} = 760\\text{ mmHg}$. Sau đó nối phần ống bên trái với một bình khí Kripton nén với áp suất $p_{\\text{Kr}} = 5\\text{ atm}$ và xả một lượng khí $V_{\\text{Kr}}$ vào, làm cho mực thủy ngân giữa hai ống thay đổi và cân bằng như hình. Cho toàn bộ quá trình diễn ra với nhiệt độ không thay đổi và nút bấc không dịch chuyển trong suốt quá trình trên.</p>",
    "optA": "Khi mực thủy ngân cân bằng, áp suất khí trong phần ống bên trái bằng tổng áp suất của $\\text{Kr}$ và áp suất của không khí trong đó.",
    "optB": "Lượng khí $\\text{Kr}$ và không khí ở phần ống bên trái đã dãn nở và đạt trạng thái đẳng nhiệt với ban đầu.",
    "optC": "Áp suất của cột khí ở bên trái bằng với áp suất của cột thủy ngân cao $9\\text{ cm}$.",
