    "deBaiChung": "",
    "nhomId": "",
    "hinhAnh": "",
    "question": "<p>Khi leo lên đỉnh Everest, các nhà leo núi phải đối mặt với sự thay đổi khắc nghiệt của áp suất và nhiệt độ, ảnh hưởng trực tiếp đến lượng khí oxygen cung cấp cho cơ thể. Giả sử coi thể tích không khí hít vào bằng dung tích phổi là $V = 5{,}0\\text{ lít}$, không khí đi vào phổi sẽ nhanh chóng được cơ thể làm nóng đến nhiệt độ $37^\\circ\\text{C}$. Coi không khí là khí lí tưởng có khối lượng mol là $29\\text{ g/mol}$ và hằng số Boltzmann $k = 1{,}38 \\cdot 10^{-23}\\text{ J/K}$. Xét tại hai vị trí:</p>\n<ul class=\"pq-sub-list\">\n<li>Tại nơi cắm trại: áp suất $p_1 = 54\\text{ kPa}$, nhiệt độ $t_1 = -3^\\circ\\text{C}$;</li>\n<li>Tại đỉnh núi: áp suất $p_2 = 33\\text{ kPa}$, nhiệt độ $t_2 = -23^\\circ\\text{C}$.</li>\n</ul>",
    "optA": "Động năng tịnh tiến trung bình của các phân tử khí tại đỉnh núi nhỏ hơn tại nơi cắm trại khoảng $4{,}14 \\cdot 10^{-22}\\text{ J}$.",
    "optB": "Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi xấp xỉ $464\\text{ m/s}$.",
