    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Độ chênh lệch động năng tịnh tiến trung bình của phân tử khí giữa nơi cắm trại ($T_1 = 270\\text{ K}$) và đỉnh núi ($T_2 = 250\\text{ K}$):<div class=\"vlxt-math-callout\">$$\\Delta W_{\\text{đ}} = W_{\\text{đ}1} - W_{\\text{đ}2} = \\frac{3}{2} k (T_1 - T_2) = \\frac{3}{2} \\cdot 1{,}38 \\cdot 10^{-23} \\cdot [(-3) - (-23)] = 4{,}14 \\cdot 10^{-22}\\text{ J}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Tốc độ căn quân phương của các phân tử khí ngoài môi trường tại đỉnh núi ($T_2 = -23 + 273 = 250\\text{ K}$, $M = 0{,}029\\text{ kg/mol}$):<div class=\"vlxt-math-callout\">$$v_{\\text{rms}} = \\sqrt{\\frac{3 R T_2}{M}} = \\sqrt{\\frac{3 \\cdot 8{,}31 \\cdot 250}{0{,}029}} \\approx 464\\text{ m/s}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Áp suất khí trong phổi cân bằng với áp suất bên ngoài tại nơi cắm trại ($p_1 = 54\\text{ kPa}$) ở nhiệt độ cơ thể $T_{\\text{phổi}} = 37 + 273 = 310\\text{ K}$. Từ phương trình Clapeyron:<div class=\"vlxt-math-callout\">$$p_1 V = \\frac{m}{M} R T_{\\text{phổi}} \\implies m = \\frac{p_1 V M}{R T_{\\text{phổi}}} = \\frac{54 \\cdot 10^3 \\cdot 5 \\cdot 10^{-3} \\cdot 29}{8{,}31 \\cdot 310} \\approx 3{,}04\\text{ g} \\neq 3{,}48\\text{ g}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Từ công thức $p = \\mu k T \\implies \\mu = \\dfrac{p}{kT}$, tỉ số mật độ phân tử khí tại hai vị trí:<div class=\"vlxt-math-callout\">$$\\frac{\\mu_2}{\\mu_1} = \\frac{p_2 T_1}{p_1 T_2} = \\frac{33 \\cdot (-3 + 273)}{54 \\cdot (-23 + 273)} = \\frac{33 \\cdot 270}{54 \\cdot 250} = \\frac{33}{50} = 66\\%$$</div>Vậy mật độ phân tử tại đỉnh núi giảm đi $100\\% - 66\\% = 34\\%$ so với tại nơi cắm trại (không phải $30\\%$).</div>",
