    "simType": "COMPRESSED_TANK_ISOCHORIC",
    "caption": "Bình khí nén sửa xe máy đặt ngoài trời nắng: nung nóng đẳng tích từ 300 K lên 360 K",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (11)",
