    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Đường sức từ của dòng điện thẳng dài là các đường tròn đồng tâm nằm trong mặt phẳng vuông góc với dây dẫn, nên vectơ cảm ứng từ $\\vec{B}_M$ tiếp tuyến với đường sức tròn tại $M$, tức phải <strong>vuông góc</strong> với đoạn thẳng nét đứt nối từ dây dẫn $I$ tới điểm $M$. Trên hình vẽ, $\\vec{B}_M$ lại hướng thẳng đứng xuống dưới (không vuông góc với đoạn nối $IM$); theo quy tắc nắm tay phải với dòng điện hướng ra ($\\odot$), $\\vec{B}_M$ đúng phải hướng chếch xuống dưới và sang phải.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Cảm ứng từ $\\vec{B}$ là đại lượng vectơ đặc trưng cho từ trường về <strong>phương diện tác dụng lực từ</strong>, không phải về mặt năng lượng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Bên ngoài một thanh nam châm, các đường sức từ có chiều đi ra từ <strong>cực Bắc ($N$)</strong> và đi vào ở <strong>cực Nam ($S$)</strong>; chỉ bên trong lòng nam châm đường sức từ mới đi từ cực Nam đến cực Bắc để tạo thành đường cong kín.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Từ trường xung quanh dây dẫn thẳng dài mang dòng điện có các đường sức là đường tròn đồng tâm (không song song cách đều) và độ lớn cảm ứng từ giảm khi ra xa dây theo quy luật:<div class=\"vlxt-math-callout\">$$B = 2 \\cdot 10^{-7}\\frac{I}{r}$$</div>Do phương, chiều và độ lớn cảm ứng từ đều thay đổi theo vị trí nên đây là từ trường <strong>không đều</strong>.</div>",
