    "question": "<p>Hình vẽ thể hiện một mô hình. Hai thanh kim loại dẫn điện và con lăn kim loại chạm vào cả hai thanh và hoàn thành mạch điện. Con lăn nằm trong từ trường do nam châm tạo ra.</p>",
