    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Quan sát hình vẽ, nam châm chữ $U$ có cực Nam ($S$) nằm ở phía trên và cực Bắc ($N$) nằm ở phía dưới. Vì đường sức từ đi ra từ cực Bắc ($N$) và đi vào cực Nam ($S$) nên trong vùng giữa hai thanh kim loại, đường sức từ vuông góc với mặt phẳng chứa hai thanh và hướng thẳng đứng từ dưới lên trên.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Đổi đơn vị $L = 6\\text{ cm} = 0{,}06\\text{ m}$. Vì con lăn vuông góc với đường sức từ, độ lớn lực từ tác dụng lên con lăn là:<div class=\"vlxt-math-callout\">$$F = I B L \\sin 90^\\circ = 2{,}5 \\cdot 1{,}2 \\cdot 0{,}06 = 0{,}18\\text{ N} \\neq 1{,}8\\text{ N}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Dòng điện đi ra từ cực dương ($+$, nối thanh phía trước) qua con lăn theo chiều từ trước ra sau để về cực âm ($-$, nối thanh phía sau). Áp dụng quy tắc bàn tay trái: đặt bàn tay trái hứng các đường sức từ hướng thẳng đứng lên trên vào lòng bàn tay, chiều từ cổ tay đến bốn ngón tay hướng từ trước ra sau thì ngón cái choãi $90^\\circ$ chỉ sang phải. Vậy lực từ hướng <strong>sang phải</strong> làm con lăn di chuyển sang phải (không phải sang trái).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Khi con lăn lăn sang phải trên hai thanh ray đặt trong từ trường đều, diện tích của mạch kín thay đổi làm từ thông qua khung biến thiên theo thời gian, từ đó xuất hiện suất điện động cảm ứng và dòng điện cảm ứng trong khung (theo định luật Lenz chống lại chuyển động của con lăn).</div>",
