    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Không sử dụng máy phát điện trong nhà hay không gian kín vì khí thải độc hại (đặc biệt là khí $\\text{CO}$) có thể tích tụ gây ngạt thở, ngộ độc chết người, đồng thời tiềm ẩn nguy cơ cháy nổ cao. Máy phát phải được đặt ở nơi thoáng khí bên ngoài, cách xa cửa sổ và cửa thông gió.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Máy phát điện gia đình thường sử dụng động cơ đốt trong chạy xăng hoặc dầu diesel; quá trình đốt cháy nhiên liệu không hoàn toàn luôn thải ra khí cacbon monoxit ($\\text{CO}$) rất độc.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Khi vận hành dưới trời mưa hoặc môi trường nồm ẩm ướt, nước dễ lọt vào đầu phát, dây dẫn và ổ cắm gây rò rỉ điện, đoản mạch, chập cháy hoặc nguy hiểm điện giật cho người sử dụng.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Với điện áp xoay chiều hình sin có giá trị hiệu dụng $U = 220\\text{ V}$, giá trị cực đại (biên độ điện áp) là $U_0 = U\\sqrt{2} = 220\\sqrt{2}\\text{ V} \\approx 311\\text{ V}$. Vì vậy điện áp tức thời biến thiên từ $-220\\sqrt{2}\\text{ V}$ đến $220\\sqrt{2}\\text{ V}$:<div class=\"vlxt-math-callout\">$$-U_0 \\le u \\le U_0 \\implies -220\\sqrt{2}\\text{ V} \\le u \\le 220\\sqrt{2}\\text{ V} \\quad (\\text{hay }-311\\text{ V} \\le u \\le 311\\text{ V})$$</div></div>",
