    "question": "<p>Hình sau mô tả sự lan truyền của một sóng điện từ trong không gian.</p>",
    "optA": "Trong sóng điện từ, hai thành phần cường độ điện trường và cảm ứng từ dao động theo phương vuông góc với nhau và vuông góc với phương truyền sóng.",
    "optB": "Trong sóng điện từ, hai thành phần cường độ điện trường và cảm ứng từ dao động cùng pha với nhau.",
