    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Theo tính chất của sóng điện từ, tại mọi điểm trên phương truyền sóng ($Ox$), vectơ cường độ điện trường $\\vec{E}$ (phương $Oy$), vectơ cảm ứng từ $\\vec{B}$ (phương $Oz$) và vectơ vận tốc truyền sóng $\\vec{v}$ (phương $Ox$) luôn đôi một vuông góc với nhau tạo thành tam diện thuận.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Tại một điểm bất kì trong không gian có sóng điện từ truyền qua, thành phần điện trường $E$ và thành phần từ trường $B$ luôn biến thiên điều hòa <strong>cùng pha</strong> nhau (đồng thời đạt cực đại, bằng $0$ hoặc đạt cực tiểu tại cùng một thời điểm).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Vì các thành phần $\\vec{E}$ và $\\vec{B}$ đều dao động theo phương vuông góc với phương truyền sóng nên <strong>sóng điện từ là sóng ngang</strong>, không phải sóng dọc.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Do $E$ và $B$ dao động cùng pha nhau nên tại thời điểm $t$ khi cường độ điện trường đạt giá trị cực tiểu (biên âm), cảm ứng từ cũng đang ở biên âm (cực tiểu). Thời gian ngắn nhất để cảm ứng từ đi từ biên âm đến biên dương (cực đại) là nửa chu kì:<div class=\"vlxt-math-callout\">$$t' = t + \\frac{T}{2} = t + \\frac{1}{2f} \\neq t + \\frac{1}{4f}$$</div></div>",
