    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-066.png",
    "question": "<p>Hình bên mô tả cấu tạo của thiết bị cân dùng từ trường. Một cuộn dây hình chữ nhật chứa $50$ vòng và có chiều rộng $d = 5\\text{ cm}$. Từ trường đều vuông góc với cuộn dây và có độ lớn $B = 0{,}2\\text{ T}$. Chỉ cạnh dưới của khung dây và một phần cạnh dài nằm trong từ trường $\\vec{B}$. Khi khóa $K$ mở và chưa đặt vật nặng lên đĩa cân thì cân thăng bằng (thanh đòn nằm ngang). Lấy $g = 10\\text{ m/s}^2$, chiều dài đòn cân hai bên bằng nhau.</p>",
    "optA": "Lực từ tác dụng lên cuộn dây khi dòng điện chạy qua là kết quả của sự tương tác giữa dòng điện và từ trường.",
    "optB": "Lực từ tác dụng lên phần cạnh dài của khung dây trong từ trường không ảnh hưởng đến độ thăng bằng của cân.",
    "optC": "Để cân có thể cân bằng khi đặt thêm vật nặng thì trọng lượng của vật nặng phải bằng lực từ tác dụng lên cuộn dây.",
    "optD": "Đặt thêm vật nặng $m$ lên đĩa cân, đóng khóa $K$. Điều chỉnh dòng điện qua cuộn dây đến $4\\text{ A}$ thì cân nằm thăng bằng, khi đó khối lượng của vật là $20\\text{ gam}$.",
