    "caption": "Hệ thống phanh tái sinh xe điện (Chế độ lái động cơ ↔ Chế độ tái sinh máy phát)",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (1)",
    "deBaiChung": "",
