    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-067.png",
    "question": "<p>Hệ thống phanh tái sinh (Regenerative Braking) là công nghệ tiêu chuẩn trên các phương tiện giao thông chạy điện. Để đơn giản, ta xét mô hình động cơ điện một chiều trong xe có cấu tạo gồm: Stator là nam châm đứng yên tạo ra từ trường và Rotor là khung dây dẫn điện có thể quay quanh trục, được nối với bánh xe. Nguyên lí hoạt động của hệ thống dựa trên sự chuyển đổi chế độ làm việc của động cơ qua hai giai đoạn:</p><ul class=\"pq-sub-list\"><li><strong>Giai đoạn xe di chuyển:</strong> Pin cấp điện vào khung dây. Dòng điện chạy trong khung dây được đặt trong vùng từ trường của nam châm và chịu tác dụng của lực từ làm khung dây quay, dẫn động bánh xe.</li><li><strong>Giai đoạn xe giảm tốc:</strong> Nguồn điện cấp cho khung dây bị ngắt. Theo quán tính, bánh xe tiếp tục quay kéo theo khung dây quay trong từ trường của nam châm. Lúc này, động cơ chuyển sang chế độ máy phát điện, biến cơ năng thành điện năng để nạp lại cho pin.</li></ul>",
    "optA": "Trong giai đoạn xe di chuyển, lực từ tác dụng lên các cạnh của khung dây tạo ra một ngẫu lực làm quay bánh xe.",
    "optB": "Trong giai đoạn xe giảm tốc, từ thông qua diện tích khung dây biến thiên là nguyên nhân sinh ra dòng điện nạp cho pin.",
    "optC": "Khi giảm tốc, dòng điện cảm ứng sinh ra trong khung dây tạo ra một ngẫu lực từ cùng chiều với chiều quay của bánh xe.",
    "optD": "Nếu đang trong quá trình nạp điện, xe đang xuống dốc với tốc độ càng cao thì công suất điện thu hồi được càng lớn.",
    "correct": "ĐĐSĐ",
