    "caption": "Ngẫu lực từ tác dụng lên khung dây chữ nhật ABCD (L × d) trong từ trường đều",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (2)",
    "deBaiChung": "",
