    "chatLuong": "tinh",
    "reviewStatus": "APPROVED",
    "rawTier": "TINH",
    "modelId": "MH-STAGING-C4-02",
    "modelTag": "DS-VD28 · DS-C4.1",
    "simType": "SILICON_MASS_DEFECT",
    "caption": "Độ hụt khối và năng lượng liên kết riêng của hạt nhân bán dẫn Silicon-28",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (DETU_12. ĐỀ SỐ 12)",
    "deBaiChung": "",
