    "caption": "Máy cán lá thép tự động điều chỉnh độ dày dựa trên tính chất đâm xuyên của tia phóng xạ beta",
    "source": "Vật Lý Xuân Trường — Tuyển Chọn Nguồn Tham Khảo (DETU_15. ĐỀ 15)",
    "deBaiChung": "",
