    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-078.png",
    "question": "<p>Hình sau mô tả một phản ứng hạt nhân. Cho biết năng lượng toả ra trong phản ứng trên là $17{,}3\\text{ MeV}$.</p>",
    "optA": "Phương trình của phản ứng là $^{1}_{1}\\text{H} + ^{2}_{1}\\text{H} \\to ^{4}_{2}\\text{He} + ^{1}_{0}\\text{n}$.",
