    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Theo định luật bảo toàn điện tích trong phản ứng hạt nhân, tổng đại số các điện tích (số hiệu nguyên tử $Z$) của các hạt tương tác trước phản ứng luôn bằng tổng đại số các điện tích của các hạt sản phẩm:<div class=\"vlxt-math-callout\">$$Z_1 + Z_2 = Z_3 + Z_4$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Theo định luật bảo toàn số nucleon (số khối $A$), tổng số nucleon của các hạt tương tác luôn bằng tổng số nucleon của các hạt sản phẩm:<div class=\"vlxt-math-callout\">$$A_1 + A_2 = A_3 + A_4$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Trong phản ứng hạt nhân <strong>không có sự bảo toàn khối lượng nghỉ</strong> (một phần khối lượng nghỉ chuyển hóa thành năng lượng hoặc ngược lại theo hệ thức $\\Delta E = (m_{\\text{trước}} - m_{\\text{sau}})c^2$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Phản ứng hạt nhân làm thay đổi cấu trúc bên trong hạt nhân (số proton $Z$ và số neutron $N$) dẫn đến sự biến đổi từ nguyên tố này sang nguyên tố khác; trong khi phản ứng hóa học chỉ thay đổi cách liên kết các electron lớp ngoài cùng nên các nguyên tố hóa học được bảo toàn.</div>",
