    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Chấm sáng tại $S$ nằm trên đường thẳng nối thẳng từ khe nguồn $N$, tức là không bị lệch trong điện trường đều. Do đó chấm sáng tại $S$ là do tia không mang điện ($\\gamma$) gây ra, còn tia $\\beta^-$ mang điện âm bị hút lệch về phía bản dương (chấm $T$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Tia $\\gamma$ là sóng điện từ không mang điện tích nên không chịu tác dụng của lực điện trường, truyền thẳng tới gây ra chấm sáng tại $S$ (không phải tại $T$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Chấm sáng tại $Q$ lệch về phía bản kim loại tích điện âm nên do các hạt mang điện dương ($\\alpha$ hoặc $\\beta^+$) gây ra. Xét theo chiều lệch lực điện trường của hạt mang điện dương về phía bản âm, chấm sáng tại $Q$ tương ứng với nhánh lệch của tia mang điện dương (tuy nhiên cần lưu ý về mặt thực nghiệm đâm xuyên: nếu tờ giấy $G$ đặt chắn ngang trước màn thì phần lớn tia $\\alpha$ bị $G$ hấp thụ mạnh hơn so với tia $\\beta^+$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Tia $\\beta^+$ (positron) có khả năng đâm xuyên mạnh hơn tia $\\alpha$ nhiều lần, dễ dàng xuyên qua một tờ giấy mỏng $G$ (chỉ bị chặn bởi tấm nhôm dày vài milimét), nên không thể bị tờ giấy $G$ chắn hết.</div>",
