    "question": "<p>Một bệnh nhân phải xạ trị (điều trị bằng đồng vị phóng xạ), dùng tia gamma để diệt tế bào bệnh. Thời gian chiếu xạ lần đầu là $20\\text{ phút}$, cứ sau $1\\text{ tháng}$ thì bệnh nhân phải tới bệnh viện để xạ trị. Biết đồng vị phóng xạ có chu kì bán rã $4\\text{ tháng}$ và vẫn dùng nguồn phóng xạ ban đầu.</p>",
    "optA": "Đồng vị phóng xạ được dùng phải là đồng vị phát ra tia alpha.",
