    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Tia $\\alpha$ có khả năng đâm xuyên rất kém (bị chặn bởi da hoặc một tờ giấy mỏng) nên không thể dùng chiếu xạ từ bên ngoài để diệt tế bào bệnh nằm sâu trong cơ thể; ở đây đề bài cũng nêu rõ nguồn dùng tia gamma ($\\gamma$) có khả năng đâm xuyên mạnh.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Xạ trị là phương pháp điều trị hiệu quả nhưng không phải \"rất an toàn\", vì tia bức xạ ion hóa có thể gây tổn thương cả các mô tế bào lành lân cận và gây ra nhiều tác dụng phụ (mệt mỏi, buồn nôn, rụng tóc, suy giảm miễn dịch...).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Vì vẫn sử dụng nguồn phóng xạ ban đầu nên độ phóng xạ $H$ của nguồn giảm dần theo thời gian ($H = H_0 \\cdot 2^{-t/T}$). Để bệnh nhân vẫn nhận được đúng liều lượng tia gamma như lần đầu ($\\Delta N \\approx H \\cdot \\Delta t = \\text{const}$), thời gian chiếu xạ $\\Delta t$ ở các lần tiếp theo phải <strong>tăng lên</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Lần chiếu xạ thứ nhất ở $t_1 = 0$ kéo dài $\\Delta t_1 = 20\\text{ phút}$. Lần chiếu xạ thứ $4$ diễn ra sau $t = 3\\text{ tháng}$. Với thời gian chiếu rất nhỏ so với chu kì bán rã ($\\Delta t \\ll T = 4\\text{ tháng}$), liều chiếu $\\Delta N = H(t)\\Delta t$ không đổi nên:<div class=\"vlxt-math-callout\">$$H_0 \\Delta t_1 = H_0 \\cdot 2^{-\\frac{t}{T}} \\cdot \\Delta t_4 \\implies \\Delta t_4 = \\Delta t_1 \\cdot 2^{\\frac{t}{T}} = 20 \\cdot 2^{\\frac{3}{4}} \\approx 33{,}64\\text{ phút} \\approx 33{,}6\\text{ phút}$$</div></div>",
    "isApproved": true,
