    "question": "<p>Ban đầu có $15{,}0\\text{ g}$ cobalt $^{60}_{27}\\text{Co}$ là chất phóng xạ với chu kì bán rã $5{,}27\\text{ năm}$ ($1\\text{ năm} = 365\\text{ ngày}$). Sản phẩm phân rã là hạt nhân bền $^{60}_{28}\\text{Ni}$.</p>",
    "optA": "Tia phóng xạ phát ra là tia $\\beta^-$.",
    "optB": "Độ phóng xạ của mẫu tại thời điểm ban đầu là $6{,}28 \\cdot 10^{14}\\text{ Bq}$.",
    "optC": "Khối lượng $^{60}_{28}\\text{Ni}$ được tạo thành sau $7{,}25\\text{ năm}$ từ thời điểm ban đầu là $5{,}78\\text{ g}$.",
    "optD": "Kể từ thời điểm ban đầu, tỉ số giữa khối lượng $^{60}_{27}\\text{Co}$ và khối lượng $^{60}_{28}\\text{Ni}$ có trong mẫu tại thời điểm $2{,}56\\text{ năm}$ là $0{,}400$.",
    "correct": "ĐĐSS",
