    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-087.png",
    "question": "<p>Các tính chất bán rã của phóng xạ được ứng dụng để chế tạo pin hạt nhân. Gần đây, các nhà khoa học Trung Quốc phát triển pin hạt nhân đầu tiên trên thế giới sử dụng đồng vị carbon $^{14}_{6}\\text{C}$, pin có thể hoạt động trong thời gian rất dài mà không cần sạc. Loại pin này thường được sử dụng trong các nhiệm vụ có yêu cầu đặc biệt như thiết bị y tế (máy tạo nhịp tim), tàu vũ trụ hoặc các thiết bị hoạt động trong môi trường khắc nghiệt như biển sâu hay vùng cực. Biết rằng hạt nhân $^{14}_{6}\\text{C}$ là đồng vị phóng xạ $\\beta^-$ với chu kì bán rã là $5730\\text{ năm}$. Độ phóng xạ ban đầu của lượng $^{14}_{6}\\text{C}$ đưa vào pin là $10\\text{ mCi}$. Lấy $1\\text{ năm} = 365\\text{ ngày}$, $1\\text{ Ci} = 3{,}7 \\cdot 10^{10}\\text{ Bq}$ và khối lượng hạt nhân tính theo đơn vị $\\text{u}$ xấp xỉ bằng số khối.</p>",
    "optA": "Hạt nhân $^{14}_{6}\\text{C}$ phóng xạ $\\beta^-$ và biến đổi thành hạt nhân $^{14}_{7}\\text{N}$.",
    "optB": "Hằng số phóng xạ của $^{14}_{6}\\text{C}$ có giá trị xấp xỉ bằng $1{,}2 \\cdot 10^{-4}\\text{ s}^{-1}$.",
