    "question": "<p>Đồng vị $^{14}_{6}\\text{C}$ là một đồng vị phóng xạ $\\beta^-$ với chu kì bán rã $5730\\text{ năm}$ (cho một năm có $365\\text{ ngày}$) theo phương trình: $$^{14}_{6}\\text{C} \\to \\text{X} + \\beta^-$$Trong các thực vật sống, khi trao đổi chất liên tục và hấp thụ carbon từ môi trường, $^{14}_{6}\\text{C}$ chiếm tỉ lệ là không đổi trong tổng số nguyên tử carbon. Khi thực vật chết đi, các hạt nhân đồng vị $^{14}_{6}\\text{C}$ phân rã và giảm dần về số hạt trong xác của thực vật (xem là cổ vật gỗ nếu thực vật là cây thân gỗ).</p>",
    "optA": "Trong phương trình phóng xạ của $^{14}_{6}\\text{C}$, $\\text{X}$ là $^{14}_{7}\\text{N}$.",
    "optB": "Từ khi thực vật chết đi, hoạt độ phóng xạ của nó giảm đều theo thời gian.",
    "optC": "Hằng số phóng xạ của $^{14}_{6}\\text{C}$ xấp xỉ bằng $3{,}8 \\cdot 10^{-12}\\text{ s}^{-1}$.",
    "optD": "Biết rằng một mẫu gỗ mới chặt có hoạt độ phóng xạ trung bình trong một giờ là $921\\text{ phân rã/giờ}$, một mẫu gỗ tương tự có hoạt độ phóng xạ trung bình trong một giờ là $497\\text{ phân rã/giờ}$. Tuổi của mẫu gỗ này là khoảng $5900\\text{ năm}$.",
