    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Áp dụng định luật bảo toàn số khối và bảo toàn điện tích với hạt $\\beta^-$ ($^{0}_{-1}\\text{e}$): $A_{\\text{X}} = 14 - 0 = 14$ và $Z_{\\text{X}} = 6 - (-1) = 7$, suy ra hạt nhân con $\\text{X}$ là $^{14}_{7}\\text{N}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Khi thực vật chết đi, nguồn $^{14}_{6}\\text{C}$ không còn được bổ sung nên hoạt độ phóng xạ giảm theo quy luật <strong>hàm số mũ</strong> $H(t) = H_0 \\cdot 2^{-t/T}$, không phải giảm đều (tuyến tính) theo thời gian.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Hằng số phóng xạ của $^{14}_{6}\\text{C}$ là:<div class=\"vlxt-math-callout\">$$\\lambda = \\frac{\\ln 2}{T} = \\frac{\\ln 2}{5730 \\cdot 365 \\cdot 24 \\cdot 3600} \\approx 3{,}84 \\cdot 10^{-12}\\text{ s}^{-1} \\approx 3{,}8 \\cdot 10^{-12}\\text{ s}^{-1}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Gọi $\\Delta t = 1\\text{ giờ}$ và $t_0$ là tuổi của mẫu cổ vật gỗ. Lập tỉ số độ phóng xạ trung bình trong $\\Delta t = 1\\text{ giờ}$ (vì $\\Delta t = 1\\text{ giờ} \\ll 5730\\text{ năm}$ nên $H(t)$ gần như không đổi trong $1\\text{ giờ}$):<div class=\"vlxt-math-callout\">$$\\frac{H_1}{H_0} = 2^{-\\frac{t_0}{T}} \\implies 2^{-\\frac{t_0}{5730}} = \\frac{497}{921} \\implies t_0 = 5730 \\cdot \\log_2\\left(\\frac{921}{497}\\right) \\approx 5099\\text{ năm} \\neq 5900\\text{ năm}$$</div></div>",
    "isApproved": true,
    "batchId": "BATCH_DS106_OFFICIAL_20261118"
