    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-090.png",
    "question": "<p>Tuổi của một chiếc thuyền cổ có thể được xác định bằng cách so sánh sự phân rã phóng xạ của $^{14}_{6}\\text{C}$ từ gỗ sống với gỗ lấy từ chiếc thuyền cổ. Một mẫu gỗ tươi gồm $3 \\cdot 10^{23}$ nguyên tử carbon được lấy ra từ một khối gỗ sống để nghiên cứu. Trong gỗ, có một trong mỗi $10^{12}$ nguyên tử carbon là đồng vị phóng xạ $^{14}_{6}\\text{C}$ có hằng số phóng xạ là $3{,}84 \\cdot 10^{-12}\\text{ s}^{-1}$. Lấy $1\\text{ năm} = 365\\text{ ngày}$. Người ta lấy từ chiếc thuyền cổ này một mẫu gỗ cổ (bằng khối lượng của mẫu gỗ tươi) và xác định được độ phóng xạ của các đồng vị phóng xạ $^{14}_{6}\\text{C}$ trong mẫu này là $0{,}65\\text{ Bq}$.</p>",
