    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Chu kì bán rã của đồng vị $^{14}_{6}\\text{C}$ (với $1\\text{ năm} = 365\\cdot 86\\,400\\text{ s}$) là:<div class=\"vlxt-math-callout\">$$T = \\frac{\\ln 2}{\\lambda} = \\frac{\\ln 2}{3{,}84 \\cdot 10^{-12} \\cdot 365 \\cdot 86\\,400} \\approx 5\\,724\\text{ năm}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Số nguyên tử phóng xạ $^{14}_{6}\\text{C}$ có trong mẫu gỗ tươi trên là:<div class=\"vlxt-math-callout\">$$N_0 = \\frac{3 \\cdot 10^{23}}{10^{12}} = 3 \\cdot 10^{11}\\text{ nguyên tử}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Độ phóng xạ ban đầu của $^{14}_{6}\\text{C}$ trong mẫu gỗ tươi là:<div class=\"vlxt-math-callout\">$$H_0 = \\lambda N_0 = 3{,}84 \\cdot 10^{-12} \\cdot 3 \\cdot 10^{11} = 1{,}152\\text{ Bq} \\ne 2\\text{ Bq}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Từ định luật phóng xạ $H_t = H_0\\, 2^{-t/T}$, tuổi của chiếc thuyền cổ là:<div class=\"vlxt-math-callout\">$$0{,}65 = 1{,}152 \\cdot 2^{-\\frac{t}{5724}} \\implies t = 5724 \\cdot \\log_2\\left(\\frac{1{,}152}{0{,}65}\\right) \\approx 4\\,726\\text{ năm} \\ne 2\\,700\\text{ năm}$$</div></div>",
