    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-091.png",
    "question": "<p>Đồng vị $^{128}_{53}\\text{I}$ là chất phóng xạ $\\beta^-$ được sử dụng trong y tế làm chất đánh dấu để đo tốc độ hấp thụ Iodine của tuyến giáp. Để xác định chu kỳ bán rã của $^{128}\\text{I}$, người ta sử dụng một đầu dò phóng xạ đặt gần mẫu $^{128}\\text{I}$ để theo dõi tín hiệu phóng xạ của mẫu theo thời gian. Số lượng tia phóng xạ mà đầu dò ghi nhận được trong mỗi giây được biểu diễn bằng số đếm trong mỗi giây (kí hiệu là $R$), và được hiển thị trên bộ đếm của đầu dò. Đồ thị trong hình vẽ biểu diễn sự phụ thuộc của $\\ln R$ theo thời gian $t$ (với $t$ tính bằng phút). Cho biết tín hiệu phóng xạ đếm được tỉ lệ thuận với độ phóng xạ của mẫu.</p>",
    "optA": "Sản phẩm phân rã phóng xạ của $^{128}\\text{I}$ là $^{128}_{52}\\text{Te}$.",
    "optB": "Thương số giữa số đếm trong mỗi lần đo và thời gian đo chính là độ phóng xạ của mẫu.",
