    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Công nghệ năng lượng hạt nhân là công nghệ khai thác năng lượng từ hạt nhân nguyên tử thông qua các lò phản ứng hạt nhân được điều khiển (có kiểm soát tốc độ phản ứng bằng thanh điều khiển).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">b — ĐÚNG</span> Trong các nhà máy điện hạt nhân thương mại đang vận hành hiện nay, năng lượng được khai thác chủ yếu từ phản ứng phân hạch hạt nhân (thường dùng nhiên liệu $^{235}_{92}\\text{U}$ hoặc $^{239}_{94}\\text{Pu}$); phản ứng tổng hợp hạt nhân (nhiệt hạch) hiện chưa được thương mại hóa ở quy mô công nghiệp.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Các nhà máy điện hạt nhân hiện nay không biến đổi trực tiếp năng lượng hạt nhân thành điện năng mà phải qua các giai đoạn trung gian: <strong>năng lượng hạt nhân $\\to$ nhiệt năng (đun sôi nước sinh hơi) $\\to$ cơ năng (quay tua-bin) $\\to$ điện năng (máy phát điện)</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Năng lượng hạt nhân không đốt nhiên liệu hóa thạch nên hầu như không phát thải khí nhà kính $\\text{CO}_2$ trong quá trình vận hành, cung cấp công suất điện nền ổn định và góp phần vào chiến lược phát triển năng lượng bền vững.</div>",
