        "statement": "Người ta chọn $^{99}_{43}\\text{Tc}$ vì chu kỳ bán rã đủ dài để chụp ảnh nhưng đủ ngắn để bệnh nhân không bị phơi nhiễm phóng xạ quá lâu.",
