    "hinhAnh": "assets/images/staging-ds/VLXT-DS-VD28-096.png",
    "question": "<p>Pin hạt nhân đang thu hút sự quan tâm lớn nhờ khả năng cung cấp năng lượng liên tục trong nhiều thập kỉ mà không cần sạc và hoạt động ổn định trong các điều kiện môi trường khắc nghiệt. Loại pin này thường được ứng dụng trong lĩnh vực hàng không vũ trụ và y tế. Một mẫu pin hạt nhân sử dụng năng lượng từ sự phân rã của đồng vị phóng xạ Niken ($^{63}_{28}\\text{Ni}$). Biết $^{63}_{28}\\text{Ni}$ là chất phóng xạ $\\beta^-$, có chu kì bán rã là $100\\text{ năm}$ và biến thành đồng vị bền của Đồng.</p>",
