        "key": "d",
        "statement": "Giả sử công suất phát điện của pin tỉ lệ thuận với độ phóng xạ. Máy tạo nhịp tim chỉ hoạt động ổn định khi công suất phát điện của pin không giảm quá $25\\%$ so với ban đầu. Nếu cấy ghép thiết bị này cho một bệnh nhân $50\\text{ tuổi}$, máy đảm bảo hoạt động an toàn đến khi bệnh nhân thọ $91\\text{ tuổi}$.",
