    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Hiện tượng phóng xạ là quá trình phân rã tự phát của một hạt nhân không bền vững, tạo thành hạt nhân mới kèm theo phát ra các tia phóng xạ ($\\alpha$, $\\beta$, $\\gamma$). Đây là một quá trình biến đổi ở cấp độ hạt nhân.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Quá trình phóng xạ mang tính chất tự phát và ngẫu nhiên hoàn toàn từ bên trong hạt nhân, <strong>không phụ thuộc</strong> và không thể điều khiển được bằng các tác động vật lí hay hóa học bên ngoài như nhiệt độ, áp suất hay điện trường, từ trường.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Trong y học hạt nhân (xạ trị áp sát hoặc điều trị đích như dùng $^{131}_{53}\\text{I}$ điều trị ung thư tuyến giáp), bệnh nhân được uống hoặc tiêm dược chất phóng xạ chọn lọc để bức xạ tiêu diệt các tế bào ung thư.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Chiếu xạ thực phẩm và nông sản bằng tia gamma (thường từ nguồn $^{60}_{27}\\text{Co}$) giúp tiêu diệt vi khuẩn, nấm mốc và ức chế nảy mầm, kéo dài thời gian bảo quản mà không làm thực phẩm bị nhiễm xạ.</div>",
