    "question": "<p>Hạt nhân $^{235}_{92}\\text{U}$ hấp thụ một neutron nhiệt rồi vỡ ra thành hai hạt nhân $^{95}_{39}\\text{Y}$ và $^{138}_{53}\\text{I}$ kèm theo giải phóng một số hạt neutron mới. Biết rằng tổng khối lượng các hạt trước phản ứng lớn hơn tổng khối lượng các hạt sau phản ứng là $0{,}181\\text{ amu}$. Lấy $1\\text{ amu} = 931{,}5\\text{ MeV}/c^2$.</p>",
    "optA": "Phản ứng trên gọi là phản ứng nhiệt hạch (phản ứng tổng hợp).",
