    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">a — SAI</span> Quá trình một hạt nhân nặng ($^{235}_{92}\\text{U}$) hấp thụ neutron rồi vỡ thành hai hạt nhân trung bình ($^{95}_{39}\\text{Y}$ và $^{138}_{53}\\text{I}$) gọi là <strong>phản ứng phân hạch</strong>, không phải phản ứng nhiệt hạch.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Áp dụng định luật bảo toàn số khối $A$ ($1 + 235 = 95 + 138 + k \\cdot 1 \\implies k = 3$):<div class=\"vlxt-math-callout\">$$^{1}_{0}\\text{n} + {}^{235}_{92}\\text{U} \\to {}^{95}_{39}\\text{Y} + {}^{138}_{53}\\text{I} + 3\\,{}^{1}_{0}\\text{n}$$</div>Quá trình này giải phóng kèm theo <strong>$3$ hạt neutron mới</strong> (hệ số nhân $k = 3$), không phải $2$ hạt.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Năng lượng tỏa ra của một phản ứng phân hạch $^{235}_{92}\\text{U}$ là:<div class=\"vlxt-math-callout\">$$\\Delta E = (m_{\\text{trước}} - m_{\\text{sau}}) c^2 = 0{,}181 \\cdot 931{,}5 \\approx 168{,}6\\text{ MeV}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Tổng số hạt nhân $^{235}_{92}\\text{U}$ bị phân hạch qua $9$ thế hệ liên tiếp (từ thế hệ $0$ kích thích ban đầu $N_0 = 10^{10}$ đến thế hệ thứ $8$, công bội $k = 3$) là:<div class=\"vlxt-math-callout\">$$N = N_0 k^0 + N_0 k^1 + \\dots + N_0 k^8 = N_0 \\frac{k^9 - 1}{k - 1}$$</div>Tổng năng lượng tỏa ra sau $9$ phân hạch dây chuyền đầu tiên:<div class=\"vlxt-math-callout\">$$Q = N \\cdot \\Delta E = 10^{10} \\cdot \\frac{3^9 - 1}{3 - 1} \\cdot 168{,}6 \\approx 1{,}66 \\cdot 10^{16}\\text{ MeV}$$</div></div>",
    "isApproved": true,
