        "statement": "Chu kì bán rã của $^{238}_{92}\\text{U}$ là $1{,}41 \\cdot 10^{17}\\text{ s}$ (làm tròn đến $2$ chữ số thập phân sau dấu phẩy).",
        "isCorrect": true
