    "subTopic": "DS-C4.5 – Phóng xạ môi trường, Chu kỳ bán rã & An toàn bức xạ",
    "topicCode": "DS-C4.5",
    "tnType": "",
    "loai": "DS",
    "type": "TRUE_FALSE_4PART",
    "mucDo": "VD",
    "chatLuong": "tinh",
