    "hinhAnh": "",
    "question": "<p>Giả sử ở một ngôi sao, sau khi chuyển hóa toàn bộ hạt nhân Hydrogen thành hạt nhân Helium thì ngôi sao lúc này chỉ có Helium với khối lượng $4{,}6 \\cdot 10^{32}\\text{ kg}$. Tiếp theo đó, Helium chuyển hóa thành hạt nhân Carbon thông qua quá trình tổng hợp:</p><div class=\"vlxt-math-callout\">$$^{4}_{2}\\text{He} + {}^{4}_{2}\\text{He} + {}^{4}_{2}\\text{He} \\to {}^{12}_{6}\\text{C} + 7{,}27\\text{ MeV}$$</div><p>Coi toàn bộ năng lượng từ quá trình tổng hợp này có công suất trung bình là $5{,}3 \\cdot 10^{30}\\text{ W}$. Cho biết khối lượng mol của $^{4}_{2}\\text{He}$ là $4\\text{ g/mol}$.</p>",
    "optA": "Phản ứng tổng hợp $^{4}_{2}\\text{He}$ thành $^{12}_{6}\\text{C}$ tỏa năng lượng.",
    "optB": "Năng lượng tỏa ra trong một ngày là $5{,}3 \\cdot 10^{30}\\text{ W}$.",
    "optC": "Số hạt $^{4}_{2}\\text{He}$ có trong khối lượng trên là $6{,}923 \\cdot 10^{58}\\text{ hạt}$.",
