    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Theo phương trình phản ứng có cộng thêm $+7{,}27\\text{ MeV} \\gt 0$ ở vế sản phẩm, quá trình tổng hợp $3$ hạt nhân $^{4}_{2}\\text{He}$ thành $^{12}_{6}\\text{C}$ là phản ứng <strong>tỏa năng lượng</strong>.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Giá trị $5{,}3 \\cdot 10^{30}\\text{ W}$ là <strong>công suất</strong> tỏa nhiệt trung bình (đơn vị Watt = $\\text{J/s}$), không phải năng lượng trong một ngày. Năng lượng tỏa ra trong $1\\text{ ngày}$ là $Q = P \\cdot t = 5{,}3 \\cdot 10^{30} \\cdot 86\\,400 \\approx 4{,}58 \\cdot 10^{35}\\text{ J}$.</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">c — ĐÚNG</span> Số hạt nhân $^{4}_{2}\\text{He}$ có trong $m = 4{,}6 \\cdot 10^{32}\\text{ kg} = 4{,}6 \\cdot 10^{35}\\text{ g}$ là:<div class=\"vlxt-math-callout\">$$N_{\\text{He}} = \\frac{m}{M} N_A = \\frac{4{,}6 \\cdot 10^{35}}{4} \\cdot 6{,}02 \\cdot 10^{23} = 6{,}923 \\cdot 10^{58}\\text{ hạt}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">d — ĐÚNG</span> Cứ $3$ hạt $^{4}_{2}\\text{He}$ tổng hợp thành $1$ hạt $^{12}_{6}\\text{C}$ thì tỏa ra $\\Delta E = 7{,}27\\text{ MeV} = 7{,}27 \\cdot 1{,}6 \\cdot 10^{-13}\\text{ J}$. Thời gian để chuyển hóa hết lượng Helium trên là:<div class=\"vlxt-math-callout\">$$t = \\frac{\\dfrac{N_{\\text{He}}}{3} \\cdot \\Delta E}{P} = \\frac{\\dfrac{6{,}923 \\cdot 10^{58}}{3} \\cdot 7{,}27 \\cdot 1{,}6 \\cdot 10^{-13}}{5{,}3 \\cdot 10^{30}} \\approx 5{,}065 \\cdot 10^{15}\\text{ s} \\approx 160{,}5\\text{ triệu năm}$$</div></div>",
    "isApproved": true,
