    "question": "<p>Một nhà máy điện hạt nhân dùng nhiên liệu uranium $^{235}_{92}\\text{U}$. Biết công suất phát điện là $500\\text{ MW}$ và hiệu suất chuyển hóa năng lượng hạt nhân thành điện năng là $20\\%$. Cho rằng khi một hạt nhân uranium $^{235}_{92}\\text{U}$ phân hạch thì tỏa ra năng lượng là $3{,}20 \\cdot 10^{-11}\\text{ J}$. Biết khối lượng mol của $^{235}_{92}\\text{U}$ là $235\\text{ g/mol}$.</p>",
