    "giaiThich": "<div class=\"exp-stmt-item\"><span class=\"exp-key-badge true\">a — ĐÚNG</span> Trong các nhà máy điện hạt nhân hiện nay, nguồn nhiệt năng được tạo ra từ phản ứng phân hạch dây chuyền có điều khiển của $^{235}_{92}\\text{U}$ (hoặc $^{239}_{94}\\text{Pu}$).</div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">b — SAI</span> Điện năng nhà máy cung cấp trong $1\\text{ giờ}$ ($3600\\text{ s}$) với công suất điện $P = 500\\text{ MW} = 5{,}0 \\cdot 10^8\\text{ W}$ là:<div class=\"vlxt-math-callout\">$$A = P \\cdot t = 5{,}0 \\cdot 10^8 \\cdot 3600 = 1{,}80 \\cdot 10^{12}\\text{ J} \\ne 0{,}50 \\cdot 10^9\\text{ J}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">c — SAI</span> Mỗi hạt nhân $^{235}_{92}\\text{U}$ phân hạch tỏa ra $\\Delta E = 3{,}20 \\cdot 10^{-11}\\text{ J} = \\dfrac{3{,}20 \\cdot 10^{-11}}{1{,}6 \\cdot 10^{-13}} = 200\\text{ MeV}$. Năng lượng tỏa ra khi phân hạch hết $1\\text{ g}\\ ^{235}_{92}\\text{U}$ là:<div class=\"vlxt-math-callout\">$$E = \\frac{1}{235} \\cdot 6{,}02 \\cdot 10^{23} \\cdot 200 \\approx 5{,}12 \\cdot 10^{23}\\text{ MeV} \\ne 1{,}93 \\cdot 10^{14}\\text{ MeV}$$</div></div>\n<div class=\"exp-stmt-item\"><span class=\"exp-key-badge false\">d — SAI</span> Trong $365\\text{ ngày}$, tổng năng lượng hạt nhân cần giải phóng với hiệu suất $H = 20\\%$ là:<div class=\"vlxt-math-callout\">$$Q_{\\text{tp}} = \\frac{P \\cdot t}{H} = \\frac{500 \\cdot 10^6 \\cdot 365 \\cdot 86\\,400}{0{,}20} = 7{,}884 \\cdot 10^{16}\\text{ J}$$</div>Khối lượng nhiên liệu $^{235}_{92}\\text{U}$ cần dùng là:<div class=\"vlxt-math-callout\">$$m = \\frac{Q_{\\text{tp}}}{\\Delta E} \\cdot \\frac{M}{N_A} = \\frac{7{,}884 \\cdot 10^{16}}{3{,}20 \\cdot 10^{-11}} \\cdot \\frac{0{,}235}{6{,}02 \\cdot 10^{23}} \\approx 961{,}8\\text{ kg} \\ne 926\\text{ kg}$$</div></div>",
